import {existsSync, readFileSync, writeFileSync} from 'node:fs'
import * as os from 'node:os'
import path from 'node:path'

import {Flags} from '@oclif/core'

import BaseCommand from '../lib/base-command.js'
import {ProcessSpawnError} from '../lib/errors.js'
import {ensureLspPatch} from '../lib/lsp-patch.js'
import {launchDriverInTmuxOrFallback, type LaunchDriverResult} from '../lib/pane-driver.js'
import {createPaneLauncher} from '../lib/pane-launcher.js'
import {readSentinelExitCode, waitForSentinelFile} from '../lib/runtime/sentinel-ipc.js'
import {spawnProcess} from '../lib/spawn.js'
import {launchTerminal} from '../lib/terminal.js'
import {enableTmuxColors, enableTmuxMouse, findToolPath, launchInTmuxSession} from '../lib/tmux-session.js'
import {checkVersionCompatibility, getClaudeCodeVersion} from '../lib/version.js'
import {EXIT_CODES} from '../types/index.js'

/**
 * Launch Claude Code or Codex with AIW configuration.
 *
 * Spawns Claude Code CLI with --dangerously-skip-permissions flag,
 * or Codex CLI with --yolo flag, enabling unattended execution.
 * Supports multiple parallel sessions.
 *
 * When already inside tmux, splits a new pane (absorbs template pane-driver logic).
 * Use --wait to block until the pane exits, --json for machine-readable output.
 */
export default class LaunchCommand extends BaseCommand {
  static override description =
    'Launch Claude Code or Codex with AIW configuration (sandbox disabled, tmux-first with inline fallback)\n\n' +
    'FLAGS\n' +
    '  --codex/-c: Launch Codex instead of Claude Code (uses --yolo flag)\n' +
    '  --new/-n: Open a new terminal in the current directory and launch there\n' +
    '  --no-tmux/-t: Launch directly in current shell instead of auto-launching tmux\n' +
    '  --tmux-session/-s: tmux session name to reuse when auto-launching tmux\n' +
    '  --prompt/-p: Initial prompt to pass to the AI REPL at startup\n' +
    '  --wait: Block until launched pane exits (for scripted callers)\n' +
    '  --json: JSON output (paneId, backend, exitCode, sentinel)\n' +
    '  --split: Split direction when in tmux (auto|h|v, default: auto)\n' +
    '  --env: Extra env vars as JSON string\n' +
    '  --prompt-path: Path to prompt file for REPL-mode tools\n\n' +
    'EXIT CODES\n' +
    '  0  Success - AI assistant launched and exited successfully\n' +
    '  1  General error - unexpected runtime failure\n' +
    '  2  Invalid usage - check your arguments and flags\n' +
    '  3  Environment error - CLI not found (install Claude Code from https://claude.ai/download, Codex from npm)'
static override examples = [
    '<%= config.bin %> <%= command.id %>  # Auto-launches tmux with a fresh session when not already in tmux',
    '<%= config.bin %> <%= command.id %> --codex  # Launch Codex with --yolo flag',
    '<%= config.bin %> <%= command.id %> --new  # Launch in a new terminal window',
    '<%= config.bin %> <%= command.id %> --no-tmux  # Run directly in current shell',
    '<%= config.bin %> <%= command.id %> --tmux-session aiw-main  # Reuse/attach explicit tmux session name',
    '<%= config.bin %> <%= command.id %> --prompt "Fix the login bug"  # Launch with initial prompt',
    '<%= config.bin %> <%= command.id %> --wait --json  # Block until pane exits, output JSON result',
    '<%= config.bin %> <%= command.id %> --split h  # Force horizontal split in tmux',
    '<%= config.bin %> <%= command.id %> --debug  # Enable verbose logging',
  ]
static override flags = {
    ...BaseCommand.baseFlags,
    codex: Flags.boolean({
      char: 'c',
      description: 'Launch Codex instead of Claude Code (uses --yolo flag for full auto mode)',
      default: false,
    }),
    env: Flags.string({
      description: 'Extra env vars as JSON object string (e.g. \'{"FOO":"bar"}\')',
      required: false,
    }),
    json: Flags.boolean({
      description: 'JSON output (paneId, backend, exitCode, sentinel)',
      default: false,
    }),
    new: Flags.boolean({
      char: 'n',
      description: 'Open a new terminal in the current directory and run aiw launch there',
      default: false,
    }),
    'no-tmux': Flags.boolean({
      char: 't',
      description: 'Launch directly in current shell instead of auto-launching tmux',
      default: false,
    }),
    prompt: Flags.string({
      char: 'p',
      description: 'Initial prompt to pass to the AI REPL at startup',
      required: false,
    }),
    'prompt-file': Flags.string({
      description: 'Path to file containing initial prompt (internal)',
      required: false,
      hidden: true,
    }),
    'prompt-path': Flags.string({
      description: 'Path to prompt file for REPL-mode tools',
      required: false,
    }),
    split: Flags.string({
      description: 'Split direction when in tmux (auto|h|v, default: auto)',
      options: ['auto', 'h', 'v'],
      required: false,
    }),
    'tmux-session': Flags.string({
      char: 's',
      description: 'tmux session name to reuse when auto-launching tmux (default: new aiw-<current-dir>-<unique> session)',
      required: false,
    }),
    wait: Flags.boolean({
      description: 'Block until launched pane exits; output result',
      default: false,
    }),
  }

  // eslint-disable-next-line complexity
  async run(): Promise<void> {
    const {flags} = await this.parse(LaunchCommand)

    // Clear Claude Code nesting-detection vars so the spawned REPL doesn't
    // refuse to start with "cannot launch claude within claude".
    delete process.env['CLAUDECODE']
    delete process.env['CLAUDE_CODE_ENTRYPOINT']

    // Patch Claude Code's LSP spawn on Windows (adds shell:true for .cmd shims)
    if (process.platform === 'win32') {
      await ensureLspPatch({
        debugLog: (msg) => this.debug(msg),
        warn: (msg) => this.warn(msg),
      })
    }

    // Determine which CLI to launch
    const useCodex = flags.codex
    const cliCommand = useCodex ? 'codex' : 'claude'
    const cliArgs = useCodex ? ['--yolo'] : ['--dangerously-skip-permissions']
    const launchFlag = useCodex ? '--codex' : ''
    const disableTmux = flags['no-tmux']
    const insideTmux = Boolean(process.env.TMUX)
    const interactiveTty = Boolean(process.stdin.isTTY && process.stdout.isTTY)
    const wantJson = flags.json
    const wantWait = flags.wait

    // Parse extra env vars
    let extraEnv: Record<string, string> = {}
    if (flags.env) {
      try {
        extraEnv = JSON.parse(flags.env)
      } catch {
        this.error('--env must be a valid JSON object string', {exit: EXIT_CODES.INVALID_USAGE})
      }
    }

    // Resolve prompt from --prompt flag, --prompt-file, or --prompt-path
    let promptText = flags.prompt?.trim() || undefined
    const promptPath = flags['prompt-path']?.trim() || undefined
    if (!promptText && flags['prompt-file']) {
      const pf = flags['prompt-file'].trim()
      try {
        if (existsSync(pf)) promptText = readFileSync(pf, 'utf8').trim() || undefined
      } catch { /* ignore — prompt is best-effort enhancement */ }
    }

    // Handle --new flag: launch in a new terminal
    if (flags.new) {
      const cwd = process.cwd()
      this.debug(`Launching new terminal in: ${cwd}`)

      let launchCmd = useCodex ? 'aiw launch --codex' : 'aiw launch'
      if (promptText) {
        const tmpFile = path.join(os.tmpdir(), `aiwcli-prompt-${Date.now()}-${process.pid}.txt`)
        writeFileSync(tmpFile, promptText, {encoding: 'utf8', mode: 0o600})
        launchCmd += ` --prompt-file ${this.shellQuote(tmpFile)}`
      }

      const result = await launchTerminal({
        cwd,
        command: launchCmd,
        debugLog: (msg) => this.debug(msg),
      })

      if (!result.success) {
        this.error(`Failed to launch new terminal: ${result.error}`, {exit: EXIT_CODES.GENERAL_ERROR})
      }

      this.log(`New terminal launched with aiw launch${launchFlag ? ` ${launchFlag}` : ''}`)
      return
    }

    // ── Pane splitting (new behavior) ──
    // When a pane manager is available (tmux, Windows Terminal, etc.),
    // use pane-driver to split a new pane instead of spawning directly.
    // Uses the abstract factory to detect the backend automatically.
    const shouldUsePaneLauncher = !disableTmux
    const paneLauncher = shouldUsePaneLauncher
      ? await createPaneLauncher({requireTmuxSession: true})
      : null
    if (paneLauncher && !flags.new) {
      this.logInfo(`Pane manager detected (${paneLauncher.backend}); splitting new pane`)
      if (insideTmux) {
        enableTmuxMouse()
        enableTmuxColors()
      }

      const splitFlag = flags.split === 'v' ? '-v' as const
        : flags.split === 'h' ? '-h' as const
          : 'auto' as const

      // Build prompt path if we have prompt text
      let effectivePromptPath = promptPath
      if (!effectivePromptPath && promptText) {
        const tmpFile = path.join(os.tmpdir(), `aiwcli-prompt-${Date.now()}-${process.pid}.txt`)
        writeFileSync(tmpFile, promptText, {encoding: 'utf8', mode: 0o600})
        effectivePromptPath = tmpFile
      }

      const driverResult = await launchDriverInTmuxOrFallback({
        toolName: cliCommand,
        mode: 'repl',
        args: cliArgs,
        env: extraEnv,
        cwd: process.cwd(),
        splitFlag,
        promptPath: effectivePromptPath,
        allowExecFallback: false,
      })

      if (wantJson) {
        await this.handleJsonOutput(driverResult, wantWait)
        return
      }

      if (!driverResult.launched) {
        // Fall back to direct spawn if pane-driver fails
        this.warn(`Pane split failed (${driverResult.reason}), launching directly`)
        const finalArgs = promptText ? [...cliArgs, promptText] : cliArgs
        const exitCode = await spawnProcess(cliCommand, finalArgs)
        this.exit(exitCode)
        return
      }

      if (driverResult.paneId) {
        this.logInfo(`Launched in tmux pane: ${driverResult.paneId}`)
      } else {
        this.logInfo(`Launched in ${driverResult.backend}`)
      }

      if (wantWait && driverResult.sentinelPath) {
        await this.waitForSentinel(driverResult)
      }

      return
    }

    // ── Normal launch flow (no pane manager detected) ──
    const shouldAutoTmux = !disableTmux && !insideTmux && interactiveTty
    let exitCode: number

    try {
      if (useCodex) {
        this.debug('Launching Codex with --yolo flag')
      } else {
        const version = await getClaudeCodeVersion()
        const versionCheck = checkVersionCompatibility(version)
        this.debug(`Claude Code version: ${versionCheck.version ?? 'unknown'}`)
        this.debug(`Compatibility status: ${versionCheck.compatible ? 'compatible' : 'incompatible'}`)
        if (versionCheck.warning) {
          this.warn(versionCheck.warning)
        }
      }

      if (shouldAutoTmux) {
        const resolvedPath = findToolPath(cliCommand)

        if (resolvedPath) {
          const sessionFromFlag = flags['tmux-session']?.trim()
          const reattach = Boolean(sessionFromFlag && sessionFromFlag.length > 0)

          let sessionName: string
          if (reattach) {
            sessionName = this.sanitizeTmuxSessionName(sessionFromFlag!)
            this.logInfo(`Launching in tmux session: ${sessionName} (reuse/attach)`)
          } else {
            const sessionBase = `aiw-${path.basename(process.cwd())}`
            sessionName = this.buildUniqueTmuxSessionName(sessionBase)
            this.logInfo(`Launching in new tmux session: ${sessionName}`)
          }

          const result = await launchInTmuxSession({
            sessionName,
            reattach,
            toolPath: resolvedPath ?? cliCommand,
            toolArgs: cliArgs,
            promptText,
          })

          if (result.usedTmux) {
            exitCode = result.exitCode
          } else {
            if (result.reason) this.logWarning(`${result.reason} — launching inline`)
            this.logInfo(`Launching ${cliCommand} inline`)
            const finalArgs = promptText ? [...cliArgs, promptText] : cliArgs
            exitCode = await spawnProcess(cliCommand, finalArgs)
          }
        } else {
          this.logWarning(`${cliCommand} not found on PATH (install from https://claude.ai/download)`)
          this.logInfo(`Launching ${cliCommand} inline`)
          const finalArgs = promptText ? [...cliArgs, promptText] : cliArgs
          exitCode = await spawnProcess(cliCommand, finalArgs)
        }
      } else {
        if (disableTmux) {
          this.logInfo('Tmux disabled via --no-tmux — launching inline')
        } else if (!interactiveTty) {
          this.logInfo('Non-interactive terminal — launching inline')
        }

        const finalArgs = promptText ? [...cliArgs, promptText] : cliArgs
        exitCode = await spawnProcess(cliCommand, finalArgs)
      }
    } catch (error) {
      if (error instanceof ProcessSpawnError) {
        this.error(error.message, {exit: EXIT_CODES.ENVIRONMENT_ERROR})
      }

      this.error('Unexpected launch failure.', {exit: EXIT_CODES.GENERAL_ERROR})
    }

    this.exit(exitCode)
  }

  private buildUniqueTmuxSessionName(base: string): string {
    const safeBase = this.sanitizeTmuxSessionName(base)
    const timestamp = Date.now().toString(36)
    const pid = process.pid.toString(36)
    return this.sanitizeTmuxSessionName(`${safeBase}-${timestamp}-${pid}`)
  }

  private async handleJsonOutput(result: LaunchDriverResult, wait: boolean): Promise<void> {
    let {exitCode} = result

    if (wait && result.launched && result.sentinelPath) {
      const finished = await waitForSentinelFile(result.sentinelPath, 14_400_000)
      exitCode = finished ? readSentinelExitCode(result.sentinelPath, 1) : -1;
    }

    const output = {
      launched: result.launched,
      backend: result.backend,
      paneId: result.paneId ?? null,
      sentinelPath: result.sentinelPath ?? null,
      exitCode: exitCode ?? null,
      reason: result.reason ?? null,
    }
    this.log(JSON.stringify(output))
    this.exit(exitCode ?? 0)
  }

  private sanitizeTmuxSessionName(input: string): string {
    const trimmed = input.trim().toLowerCase()
    const safe = trimmed
      .replaceAll(/[^a-z0-9_-]/g, '-')
      .replaceAll(/-+/g, '-')
      .replaceAll(/^[-_]+|[-_]+$/g, '')
    return safe || 'aiw'
  }

  private shellQuote(input: string): string {
    return `'${input.replaceAll("'", `'"'"'`)}'`
  }

  private async waitForSentinel(result: LaunchDriverResult): Promise<void> {
    if (!result.sentinelPath) return
    const finished = await waitForSentinelFile(result.sentinelPath, 14_400_000)
    if (finished) {
      const exitCode = readSentinelExitCode(result.sentinelPath, 1)
      this.exit(exitCode)
    } else {
      this.exit(1)
    }
  }
}

/**
 * Formatting module for context display output.
 * See SPEC.md §11
 *
 * All functions accept a ContextState with fields:
 *   id, summary, mode, lastActive, planPath, handoffPath,
 *   tasks[], lastSession, sessionIds, status, method, tags
 */

import * as fs from "node:fs";
import path from "node:path";

import { getContextDir } from "../runtime/constants.js";
import { displayPath, parseIsoTimestamp } from "../runtime/utils.js";
import type { ContextState, Task } from "../types.js";

const MAX_PLAN_INLINE_CHARS = 30_000;


// ---------------------------------------------------------------------------
// Mode display
// ---------------------------------------------------------------------------

const MODE_DISPLAY_MAP: Record<string, string> = {
  idle: "",
  hasStagedWork: "[Staged]", // CHANGED: unified mode (plan or handoff)
  active: "[Active]",
};

/**
 * Get bracketed display string for mode, or empty for idle.
 * See SPEC.md §11.2
 */
export function getModeDisplay(mode: string): string {
  return MODE_DISPLAY_MAP[mode] ?? "";
}

// ---------------------------------------------------------------------------
// Time formatting
// ---------------------------------------------------------------------------

/**
 * Format ISO timestamp as '2 hours ago', 'yesterday', etc.
 * See SPEC.md §11.3
 */
export function formatRelativeTime(isoTimestamp: null | string): string {
  if (!isoTimestamp) return "unknown";

  const dt = parseIsoTimestamp(isoTimestamp);
  if (!dt) return isoTimestamp.slice(0, 16);

  const now = new Date();

  // Strip timezone info for comparison
  const diffMs = now.getTime() - dt.getTime();
  const diffSec = Math.floor(diffMs / 1000);
  const diffMin = Math.floor(diffSec / 60);
  const diffHours = Math.floor(diffMin / 60);
  const diffDays = Math.floor(diffHours / 24);

  if (diffDays === 0) {
    if (diffHours === 0) {
      if (diffMin === 0) return "just now";
      return diffMin === 1 ? "1 minute ago" : `${diffMin} minutes ago`;
    }

    return diffHours === 1 ? "1 hour ago" : `${diffHours} hours ago`;
  }

  if (diffDays === 1) return "yesterday";
  if (diffDays < 7) return `${diffDays} days ago`;

  // Older: show date
  const year = dt.getFullYear();
  const month = String(dt.getMonth() + 1).padStart(2, "0");
  const day = String(dt.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

function taskAttr(task: Record<string, unknown> | Task, key: string, defaultVal = ""): string {
  if (typeof task === "object" && task !== null) {
    return (task as unknown)[key] ?? defaultVal;
  }

  return defaultVal;
}

function readPlanContent(planPath: string): [null | string, boolean, number] {
  try {
    if (!fs.existsSync(planPath)) return [null, false, 0];
    const content = fs.readFileSync(planPath, "utf8");
    const total = content.length;
    if (total > MAX_PLAN_INLINE_CHARS) {
      return [content.slice(0, MAX_PLAN_INLINE_CHARS), true, total];
    }

    return [content, false, total];
  } catch {
    return [null, false, 0];
  }
}

function modeLabel(ctx: ContextState): string {
  const d = getModeDisplay(ctx.mode ?? "idle");
  return d ? d.replaceAll(/^\[|\]$/g, "") : "Active";
}

/**
 * Build restore sections from lastSession, tasks, and planPath.
 * See SPEC.md §11.4
 */
export function buildRestoreSections(
  ctx: ContextState,
  projectRoot?: string,
  inlinePlan = false,
): string {
  const sections: string[] = [];
  const lastSession = ctx.lastSession ?? {};

  if (lastSession) {
    const savedAt = lastSession.saved_at ?? "";
    if (savedAt) {
      const reason = lastSession.save_reason ?? "";
      const reasonDisplay = reason ? reason.replaceAll('_', " ") : "unknown";
      sections.push(`**Last session ended:** ${formatRelativeTime(savedAt)} (${reasonDisplay})`);
    }
  }

  const tasks = ctx.tasks ?? [];
  if (tasks.length > 0) {
    const buckets: Record<string, string[]> = {
      completed: [],
      inProgress: [],
      pending: [],
      blocked: [],
    };
    for (const t of tasks) {
      const s = taskAttr(t, "status", "pending");
      if (buckets[s]) {
        buckets[s]!.push(taskAttr(t, "subject"));
      }
    }

    if (Object.values(buckets).some(b => b.length > 0)) {
      sections.push("", `### Previous Work (${tasks.length} tasks)`, "");
      const marks: Record<string, string> = {
        completed: "[x]",
        inProgress: "[~]",
        pending: "[ ]",
        blocked: "[!]",
      };
      for (const [status, mark] of Object.entries(marks)) {
        for (const subj of buckets[status] ?? []) {
          sections.push(`- ${mark} ${subj}`);
        }
      }
    }
  }

  const {planPath} = ctx;
  if (planPath) {
    if (inlinePlan) {
      const [content, truncated, totalChars] = readPlanContent(planPath);
      if (content) {
        let header = `Plan loaded from: \`${displayPath(planPath)}\``;
        if (truncated) header += ` (truncated, ${totalChars} chars total)`;
        sections.push("", "### Plan", header, "", content);
        if (truncated) {
          sections.push(`\n*Plan truncated at ${MAX_PLAN_INLINE_CHARS} characters. Full plan at: \`${displayPath(planPath)}\`*`);
        }
      } else {
        sections.push("", "### Plan", `*Plan file not found at \`${displayPath(planPath)}\`.*`);
      }
    } else {
      sections.push("", "### Plan", `Read the plan at: \`${displayPath(planPath)}\``);
    }
  }

  const gitState = lastSession?.git_state ?? {};
  if (gitState && Object.keys(gitState).length > 0) {
    const branch = gitState.branch ?? "unknown";
    const uncommitted: string[] = gitState.uncommittedFiles ?? [];
    const lastCommit = gitState.lastCommitShort ?? "";
    let uncStr = uncommitted.length > 0 ? uncommitted.slice(0, 5).join(", ") : "none";
    if (uncommitted.length > 5) uncStr += ` (+${uncommitted.length - 5} more)`;
    sections.push("", "### Git State", `Branch: ${branch} | Uncommitted: ${uncStr}`);
    if (lastCommit) sections.push(`Last commit: ${lastCommit}`);
  }

  return sections.join("\n");
}

function resumeBlock(ctx: ContextState, projectRoot: string | undefined, modeText: string, instructions: string[]): string {
  const lines = [
    `## Resuming Context: ${ctx.id}`, "",
    `**Summary:** ${ctx.summary}`,
    `**Mode:** ${modeText}`,
  ];
  const restore = buildRestoreSections(ctx, projectRoot, true);
  if (restore) lines.push(restore);
  lines.push("", "---", "", "**Instructions:**", ...instructions);
  return lines.join("\n");
}

// ---------------------------------------------------------------------------
// Public formatters
// ---------------------------------------------------------------------------

/**
 * Format output when resuming a context with a pending handoff.
 * See SPEC.md §11.5
 */
export function formatHandoffContinuation(ctx: ContextState, projectRoot?: string): string {
  const handoffPath = ctx.handoffPath ?? "";
  const lines = [
    `## Resuming Context: ${ctx.id} (Handoff Available)`, "",
    `**Summary:** ${ctx.summary}`,
    `**Mode:** Implementing (handoff from previous session)`, "",
  ];

  try {
    if (handoffPath && fs.existsSync(handoffPath)) {
      lines.push("### Previous Session Handoff", "", fs.readFileSync(handoffPath, "utf8"), "");
    } else {
      lines.push(`*Handoff document not found at \`${displayPath(handoffPath)}\`*`, "");
    }
  } catch (error: unknown) {
    lines.push(`*Handoff document at \`${displayPath(handoffPath)}\` could not be read: ${error}*`, "");
  }

  const restore = buildRestoreSections(ctx, projectRoot, true);
  if (restore) lines.push(restore);

  lines.push("", "---", "", "**Instructions:**",
    "1. Review the handoff document above - especially dead ends",
    "2. Check the plan file for remaining tasks",
    "3. Continue implementation from where the previous session left off");
  return lines.join("\n");
}

/**
 * Build lightweight orientation for external agents (Codex, etc.).
 * Tells the agent where the context folder and key paths are — no session state.
 */
export function buildExternalAgentContext(
  ctx: ContextState,
  projectRoot: string,
): string {
  const contextDir = getContextDir(ctx.id, projectRoot);
  const notesDir = path.join(contextDir, "notes");
  const lines = [
    "## Project Context",
    "",
    `- **Context ID:** ${ctx.id}`,
    `- **Context folder:** ${displayPath(contextDir)}`,
    `- **Notes folder:** ${displayPath(notesDir)}`,
  ];
  return lines.join("\n");
}

/**
 * Format output for pending plan implementation (mode=has_plan).
 * See SPEC.md §11.6
 */
export function formatPlanContinuation(ctx: ContextState, projectRoot?: string): string {
  return resumeBlock(ctx, projectRoot, "Pending Implementation", [
    "1. Review the plan and previous work above",
    "2. Continue from where the previous session left off",
  ]);
}

/**
 * Format output for ongoing implementation (mode=active).
 * See SPEC.md §11.7
 */
export function formatActiveContinuation(ctx: ContextState, projectRoot?: string): string {
  return resumeBlock(ctx, projectRoot, "Implementing", [
    "1. Review the plan and previous work above",
    "2. Continue from where the previous session left off",
  ]);
}

/**
 * Format list of contexts for display.
 * See SPEC.md §11.8
 */
export function formatContextList(contexts: ContextState[]): string {
  if (contexts.length === 0) return "No active contexts found.";

  const lines = ["## Active Contexts\n"];
  for (const [i, context_] of contexts.entries()) {
    const ctx = context_!;
    const timeStr = formatRelativeTime(ctx.lastActive);
    const md = getModeDisplay(ctx.mode ?? "idle");
    const si = md ? ` ${md}` : "";
    lines.push(`**${i + 1}. ${ctx.id}**${si}`, `   ${ctx.summary}`);
    if (ctx.method) {
      lines.push(`   Method: ${ctx.method} | Last active: ${timeStr}`);
    } else {
      lines.push(`   Last active: ${timeStr}`);
    }

    lines.push("");
  }

  return lines.join("\n");
}

/**
 * Format notification for a newly created context.
 * See SPEC.md §11.9
 */
export function formatContextCreated(ctx: ContextState): string {
  return [
    `## Context Created: ${ctx.id}`, "",
    `**Summary:** ${ctx.summary}`, "",
    "A new context has been created for this work.",
    "Tasks created with TaskCreate will be persisted to this context.",
  ].join("\n");
}

/**
 * Format system reminder: lightweight (per-prompt) or rich (first-bind restore).
 * See SPEC.md §11.10
 */
export function formatActiveContextReminder(
  ctx: ContextState,
  projectRoot?: string,
  includeRestore = false,
): string {
  const timeStr = formatRelativeTime(ctx.lastActive);
  const label = modeLabel(ctx);

  if (includeRestore) {
    const lines = [
      `## Resuming Context: ${ctx.id}`, "",
      `**Summary:** ${ctx.summary}`,
      `**Mode:** ${label}`,
    ];
    const restore = buildRestoreSections(ctx, projectRoot, true);
    if (restore) lines.push(restore);
    lines.push("", "---", "", "**Instructions:**",
      "1. Review the previous work above",
      "2. Continue from where the previous session left off");
    return lines.join("\n");
  }

  return [
    `## Active Context: ${ctx.id}`, "",
    `**Summary:** ${ctx.summary}`,
    `**Mode:** ${label}`,
    `**Last Active:** ${timeStr}`, "",
    `All work belongs to context "${ctx.id}".`,
    "Tasks created with TaskCreate will be persisted to this context.",
  ].join("\n");
}

// ---------------------------------------------------------------------------
// Picker / command feedback
// ---------------------------------------------------------------------------

/**
 * Format the boxed picker shown on stderr when blocking for selection.
 * See SPEC.md §11.11
 */
export function formatContextPickerStderr(contexts: ContextState[]): string {
  const lines = [
    "",
    "+----------------------------------------------------------------+",
    "|                   CONTEXT SELECTION REQUIRED                   |",
    "+----------------------------------------------------------------+",
  ];

  let selectableCount = 0;
  for (const [i, context_] of contexts.entries()) {
    const ctx = context_!;
    const timeStr = formatRelativeTime(ctx.lastActive);
    const mode = ctx.mode ?? "idle";
    const isSelectable = mode === "active" || Boolean(ctx.handoffPath);
    if (isSelectable) selectableCount++;

    let status = "";
    if (ctx.handoffPath) {
      status = " [Handoff Ready]";
    } else if (getModeDisplay(mode)) {
      status = ` ${getModeDisplay(mode)}`;
    }

    const summary = ctx.summary.length > 48 ? ctx.summary.slice(0, 45) + "..." : ctx.summary;
    const selTag = isSelectable ? " [selectable]" : " [end only]";

    lines.push(`|  ^${i + 1}  ${ctx.id}${status}${selTag}`, `|       ${summary}`, `|       [${timeStr}]`, "|");
  }

  lines.push(
    "+----------------------------------------------------------------+",
    "|  Usage:                                                        |",
    "|    ^S<N>                 - Select context by number            |",
    "|    ^E<N>                 - End/complete context by number      |",
    "|    ^S:query              - Select by ID match (race-safe)       |",
    "|    ^E:query              - End by ID match (race-safe)         |",
    "|    ^E<N>+                - End context N and all after         |",
    "|    ^E*                   - End ALL contexts                    |",
    "|    ^E1E2S3               - End #1 and #2, select #3           |",
    "|    ^E:fooS:bar           - End 'foo...', select 'bar...'       |",
    "|    ^0 work description   - Create new context (10+ chars)     |",
    "+----------------------------------------------------------------+",
  );

  if (selectableCount === 0) {
    lines.push(
      "|  NOTE: No selectable contexts.                                |",
      "|        Use ^E<N> to end old contexts, then ^0 to create new.  |",
      "+----------------------------------------------------------------+",
    );
  }

  lines.push("");
  return lines.join("\n");
}

/**
 * Format feedback about caret command operations performed.
 * See SPEC.md §11.12
 */
export function formatCommandFeedback(
  endedContexts: ContextState[],
  selectedContext: ContextState | null,
): string {
  const lines: string[] = [];
  if (endedContexts.length > 0) {
    lines.push("## Contexts Ended", "");
    for (const ctx of endedContexts) {
      const s = ctx.summary.length > 50 ? ctx.summary.slice(0, 50) + "..." : ctx.summary;
      lines.push(`- **${ctx.id}**: ${s}`);
    }

    lines.push("");
  }

  if (selectedContext) {
    const label = modeLabel(selectedContext);
    const timeStr = formatRelativeTime(selectedContext.lastActive);
    lines.push(
      `## Active Context: ${selectedContext.id}`, "",
      `**Summary:** ${selectedContext.summary}`,
      `**Mode:** ${label}`,
      `**Last Active:** ${timeStr}`, "",
      `All work belongs to context "${selectedContext.id}".`,
      "Tasks created with TaskCreate will be persisted to this context.",
    );
  }

  return lines.join("\n");
}

// ---------------------------------------------------------------------------
// Context Inventory
// ---------------------------------------------------------------------------

/** Collector function: scans one aspect of the context folder, returns markdown or null. */
type InventoryCollector = (
  contextId: string,
  contextDir: string,
  state: ContextState,
) => null | string;

/** Descriptions for known context subfolders. */
const KNOWN_FOLDERS: Record<string, string> = {
  "plans": "Archived implementation plans from plan mode",
  "session-transcripts": "JSONL records of previous agent sessions — read these to understand prior work",
  "handoffs": "Structured briefing documents for session continuity",
  "reviews": "Plan review artifacts (reviewer verdicts, corroboration reports)",
  "notes": "Analysis files, reports, and documentation that don't belong in the codebase",
};

function collectFolderPath(contextId: string, contextDir: string, _state: ContextState): null | string {
  if (!fs.existsSync(contextDir)) return null;
  return `**Context folder:** \`${displayPath(contextDir)}\`\n**State file:** \`${displayPath(path.join(contextDir, "state.json"))}\` — contains session history, task records, plan/handoff metadata`;
}

function collectStatePointers(contextId: string, contextDir: string, state: ContextState): null | string {
  const pointers: string[] = [];
  if (state.planPath) {
    const exists = fs.existsSync(state.planPath);
    pointers.push(`- **Active plan:** \`${displayPath(state.planPath)}\`${exists ? "" : " (not found)"}`);
  }

  if (state.handoffPath) {
    const exists = fs.existsSync(state.handoffPath);
    pointers.push(`- **Active handoff:** \`${displayPath(state.handoffPath)}\`${exists ? "" : " (not found)"}`);
  }

  if (pointers.length === 0) return null;
  return "**Key artifacts:**\n" + pointers.join("\n");
}

function countFilesRecursive(dirPath: string): number {
  let count = 0;
  try {
    const entries = fs.readdirSync(dirPath, { withFileTypes: true });
    for (const entry of entries) {
      if (entry.isFile()) {
        count++;
      } else if (entry.isDirectory()) {
        count += countFilesRecursive(path.join(dirPath, entry.name));
      }
    }
  } catch { /* permission errors, etc. */ }

  return count;
}

function collectFolderInventory(contextId: string, contextDir: string, _state: ContextState): null | string {
  if (!fs.existsSync(contextDir)) return null;
  let entries: fs.Dirent[];
  try {
    entries = fs.readdirSync(contextDir, { withFileTypes: true });
  } catch { return null; }

  const dirs = entries.filter(e => e.isDirectory()).sort((a, b) => a.name.localeCompare(b.name));
  if (dirs.length === 0) return null;

  const lines: string[] = ["**Available folders:**"];
  for (const dir of dirs) {
    const dirPath = path.join(contextDir, dir.name);
    const desc = KNOWN_FOLDERS[dir.name] ?? "Project-specific artifacts";
    const fileCount = countFilesRecursive(dirPath);
    lines.push(`- \`${dir.name}/\` — ${desc} (${fileCount} file${fileCount === 1 ? "" : "s"})`);
  }

  return lines.join("\n");
}

function collectSessionStats(contextId: string, contextDir: string, state: ContextState): null | string {
  const sessionCount = (state.sessionIds ?? []).length;
  if (sessionCount === 0) return null;

  const transcriptsDir = path.join(contextDir, "session-transcripts");
  let transcriptCount = 0;
  let timeRange = "";

  if (fs.existsSync(transcriptsDir)) {
    try {
      const files = fs.readdirSync(transcriptsDir).filter(f => f.endsWith(".jsonl")).sort();
      transcriptCount = files.length;
      if (files.length > 1) {
        const oldest = files[0]!.slice(0, 10);
        const newest = files.at(-1)!.slice(0, 10);
        if (oldest !== newest) timeRange = ` (${oldest} to ${newest})`;
      }
    } catch { /* ignore */ }
  }

  let line = `**Sessions:** ${sessionCount} total`;
  if (transcriptCount > 0) {
    line += `, ${transcriptCount} transcript${transcriptCount === 1 ? "" : "s"} archived${timeRange}`;
  }

  return line;
}

function collectNotesGuidance(contextId: string, contextDir: string, _state: ContextState): null | string {
  const notesDir = path.join(contextDir, "notes");
  return `**Notes:** Put notes and files that don't belong in the codebase here. Reference them in other documents as needed: \`${displayPath(notesDir)}\``;
}

/** Ordered list of inventory collectors. Append new collectors here. */
const INVENTORY_COLLECTORS: InventoryCollector[] = [
  collectFolderPath,
  collectStatePointers,
  collectFolderInventory,
  collectSessionStats,
  collectNotesGuidance,
];

/**
 * Build a markdown inventory of resources available in the context folder.
 * Returns null if the context folder doesn't exist yet (brand new context).
 */
export function buildContextInventory(
  state: ContextState,
  projectRoot: string,
): null | string {
  const contextDir = getContextDir(state.id, projectRoot);
  if (!fs.existsSync(contextDir)) return null;

  const sections = INVENTORY_COLLECTORS
    .map(c => c(state.id, contextDir, state))
    .filter((s): s is string => s !== null);

  if (sections.length === 0) return null;
  return "### Context Resources\n\n" + sections.join("\n\n");
}

/**
 * Context selection — determines which context a prompt belongs to.
 * See SPEC.md §8
 *
 * Single entry point: determineContext(prompt, sessionId, projectRoot)
 * Returns [contextId, method, outputText].
 *
 * Selection priority:
 * 1. session_match       — sessionId found in index.json sessions map
 * 2. caret_command       — prompt starts with ^ → parse and execute
 * 3. plan_content_match  — FALLBACK: match against has_plan contexts
 * 3b. handoff_match      — FALLBACK: match against has_handoff contexts
 * 4. default             — create new context
 */

import * as crypto from "node:crypto";

import {
  formatActiveContextReminder,
  formatCommandFeedback,
  formatContextCreated,
  formatContextPickerStderr,
  formatHandoffContinuation,
  formatPlanContinuation,
} from "./context-formatter.js";
import {
  bindSession,
  completeContext,
  createContext,
  createContextFromPrompt,
  determineArtifactType,
  getAllContexts,
  getContext,
  getContextBySessionId,
  updateMode,
} from "./context-store.js";
import { normalizePlanContent } from "./plan-manager.js";
import { logDebug, logError, logInfo } from "../runtime/logger.js";
import { isInternalCall } from "../runtime/subprocess-utils.js";
import type { CaretCommand, ContextState } from "../types.js";

/** Minimum characters required for new context description. */
const MIN_NEW_CONTEXT_CHARS = 10;

/**
 * Raised when the request should be blocked with a message to user.
 * See SPEC.md §8.2
 */
export class BlockRequest extends Error {
  constructor(message: string) {
    super(message);
    this.name = "BlockRequest";
    // Maintains proper prototype chain when transpiled to ES5
    Object.setPrototypeOf(this, BlockRequest.prototype);
  }
}

// ---------------------------------------------------------------------------
// Context prefix resolution
// ---------------------------------------------------------------------------

/**
 * Resolve a context ID query to an index (1-based) using tiered matching.
 * Match priority: exact > prefix > substring (all case-insensitive).
 * Returns [index, null] on unique match, [null, error] on 0 or 2+ matches.
 * See SPEC.md §8.3
 */
export function resolveContextByPrefix(
  query: string,
  contexts: ContextState[],
): [null | number, null | string] {
  const q = query.toLowerCase();
  const available = contexts.map(c => c.id).join(", ");

  // Tier 1: Exact match
  const exact = contexts
    .map((ctx, i) => [i + 1, ctx] as const)
    .filter(([, ctx]) => ctx.id.toLowerCase() === q);
  if (exact.length === 1) return [exact[0]![0], null];

  // Tier 2: Prefix match
  const prefix = contexts
    .map((ctx, i) => [i + 1, ctx] as const)
    .filter(([, ctx]) => ctx.id.toLowerCase().startsWith(q));
  if (prefix.length === 1) return [prefix[0]![0], null];
  if (prefix.length > 1) {
    return [null, `Ambiguous match '${query}' — ${prefix.length} prefix matches: ${prefix.map(([, c]) => c.id).join(", ")}. Be more specific.`];
  }

  // Tier 3: Substring match
  const substr = contexts
    .map((ctx, i) => [i + 1, ctx] as const)
    .filter(([, ctx]) => ctx.id.toLowerCase().includes(q));
  if (substr.length === 1) return [substr[0]![0], null];
  if (substr.length > 1) {
    return [null, `Ambiguous match '${query}' — ${substr.length} substring matches: ${substr.map(([, c]) => c.id).join(", ")}. Be more specific.`];
  }

  return [null, `No context matches '${query}'. Available: ${available}`];
}

// ---------------------------------------------------------------------------
// Caret command parsing
// ---------------------------------------------------------------------------

/**
 * Parse chained caret commands from user prompt.
 * See SPEC.md §8.4
 */
export function parseChainedCaret(
  prompt: string,
  contexts: ContextState[],
): [CaretCommand | null, null | string] {
  if (!prompt.startsWith("^")) return [null, null];

  const match = prompt.match(/^\^(\S+)(?:\s+(.*))?$/s);
  if (!match) {
    return [null, "Invalid prefix. Use ^E<N> to end, ^S<N> to select, or ^0 <desc> for new context."];
  }

  const commandStr = match[1]!;
  const remaining = (match[2] ?? "").trim();

  // ^N shorthand
  if (/^\d+$/.test(commandStr)) {
    const num = Number.parseInt(commandStr, 10);
    if (num === 0) {
      if (remaining.length < MIN_NEW_CONTEXT_CHARS) {
        return [null,
          `Please provide a longer description for your new context.\n` +
          `Your description '${remaining}' is only ${remaining.length} characters.\n` +
          `Minimum required: ${MIN_NEW_CONTEXT_CHARS} characters.\n` +
          `Example: ^0 implement user authentication with JWT tokens`,
        ];
      }

      return [{ ends: [], select: null, newContextDesc: remaining, remainingPrompt: "" }, null];
    }

    if (num < 1 || num > contexts.length) {
      if (contexts.length === 0) {
        return [null, "No existing contexts. Use ^0 <description> to create a new one."];
      }

      return [null, `Invalid selection. Choose 1-${contexts.length} for existing contexts, or ^0 for new.`];
    }

    const ctx = contexts[num - 1]!;
    return [{ ends: [], select: ctx.id, newContextDesc: null, remainingPrompt: remaining }, null];
  }

  // Parse chained commands
  const ends: string[] = [];
  let select: null | string = null;
  let pos = 0;

  while (pos < commandStr.length) {
    const ch = commandStr[pos]!.toUpperCase();

    if (ch === "E") {
      pos++;
      if (pos < commandStr.length && commandStr[pos] === "*") {
        pos++;
        if (contexts.length === 0) return [null, "No contexts to end."];
        for (const ctx of contexts) {
          if (!ends.includes(ctx.id)) ends.push(ctx.id);
        }
      } else if (pos < commandStr.length && commandStr[pos] === ":") {
        pos++;
        const prefixStart = pos;
        while (pos < commandStr.length && !/[EeSs]/.test(commandStr[pos]!)) pos++;
        const pfx = commandStr.slice(prefixStart, pos);
        if (!pfx) return [null, "Expected ID query after 'E:'"];
        const [idx, err] = resolveContextByPrefix(pfx, contexts);
        if (err) return [null, err];
        const ctx = contexts[idx! - 1]!;
        if (!ends.includes(ctx.id)) ends.push(ctx.id);
      } else {
        const numStart = pos;
        while (pos < commandStr.length && /\d/.test(commandStr[pos]!)) pos++;
        if (numStart === pos) {
          return [null, `Expected number, '*', or ':prefix' after 'E' at position ${numStart + 1}`];
        }

        const num = Number.parseInt(commandStr.slice(numStart, pos), 10);
        if (num < 1 || num > contexts.length) {
          if (contexts.length === 0) return [null, "No contexts to end."];
          return [null, `Context ^E${num} invalid. Choose 1-${contexts.length}.`];
        }

        if (pos < commandStr.length && commandStr[pos] === "+") {
          pos++;
          for (let i = num; i <= contexts.length; i++) {
            const ctx = contexts[i - 1]!;
            if (!ends.includes(ctx.id)) ends.push(ctx.id);
          }
        } else {
          const ctx = contexts[num - 1]!;
          if (!ends.includes(ctx.id)) ends.push(ctx.id);
        }
      }
    } else if (ch === "S") {
      pos++;
      let ctx: ContextState;
      if (pos < commandStr.length && commandStr[pos] === ":") {
        pos++;
        const prefixStart = pos;
        while (pos < commandStr.length && !/[EeSs]/.test(commandStr[pos]!)) pos++;
        const pfx = commandStr.slice(prefixStart, pos);
        if (!pfx) return [null, "Expected ID query after 'S:'"];
        const [idx, err] = resolveContextByPrefix(pfx, contexts);
        if (err) return [null, err];
        ctx = contexts[idx! - 1]!;
      } else {
        const numStart = pos;
        while (pos < commandStr.length && /\d/.test(commandStr[pos]!)) pos++;
        if (numStart === pos) {
          return [null, `Expected number or ':prefix' after 'S' at position ${numStart + 1}`];
        }

        const num = Number.parseInt(commandStr.slice(numStart, pos), 10);
        if (num < 1 || num > contexts.length) {
          if (contexts.length === 0) return [null, "No contexts to select."];
          return [null, `Context ^S${num} invalid. Choose 1-${contexts.length}.`];
        }

        ctx = contexts[num - 1]!;
      }

      if (select === null) select = ctx.id;
    } else {
      return [null,
        `Invalid command '${commandStr[pos]}' at position ${pos + 1}.\n` +
        `Use E<N> to end, E<N>+ to end N and after, E* to end all, S<N> to select.\n` +
        `Example: ^E1S2 (end 1, select 2), ^E2+ (end 2 and older), ^E* (end all)`,
      ];
    }
  }

  if (select !== null && ends.includes(select)) {
    return [null, `Cannot select context '${select}' because it's being ended.`];
  }

  return [{ ends, select, newContextDesc: null, remainingPrompt: remaining }, null];
}

// ---------------------------------------------------------------------------
// Plan content matching (fallback)
// ---------------------------------------------------------------------------

function matchPlanContent(prompt: string, hasPlanContexts: ContextState[]): ContextState | null {
  if (hasPlanContexts.length === 0) return null;

  // Tier 1: Plan ID match
  const idMatch = prompt.match(/<!-- plan-id: ([a-f0-9]+) -->/);
  if (idMatch) {
    const foundId = idMatch[1]!;
    for (const ctx of hasPlanContexts) {
      if (ctx.planId === foundId) {
        logDebug("context_selector", `Tier 1 plan-id match: ${ctx.id} (id: ${foundId})`);
        return ctx;
      }
    }
  }

  // Tier 2: Normalized hash match
  const normalized = normalizePlanContent(prompt);
  const normHash = crypto.createHash("sha256").update(normalized, "utf8").digest("hex").slice(0, 12);
  for (const ctx of hasPlanContexts) {
    if (ctx.planHash && ctx.planHash === normHash) {
      logDebug("context_selector", `Tier 2 normalized hash match: ${ctx.id} (hash: ${normHash})`);
      return ctx;
    }
  }

  // Tier 3: Multi-anchor signature match
  for (const ctx of hasPlanContexts) {
    const anchors = ctx.planAnchors ?? [];
    if (anchors.length > 0) {
      const hits = anchors.filter(a => prompt.includes(a)).length;
      if (hits >= 2 && hits >= Math.floor(anchors.length / 2)) {
        logDebug("context_selector", `Tier 3 anchor match: ${ctx.id} (${hits}/${anchors.length} anchors)`);
        return ctx;
      }
    }
  }

  // Tier 4 (legacy): Signature match
  const promptHead = new Set(prompt.slice(0, 500));
  for (const ctx of hasPlanContexts) {
    if (ctx.planSignature && promptHead.has(ctx.planSignature)) {
      logDebug("context_selector", `Tier 4 legacy signature match: ${ctx.id}`);
      return ctx;
    }
  }

  return null;
}

// ---------------------------------------------------------------------------
// Context creation helper
// ---------------------------------------------------------------------------

function createNewContext(
  prompt: string,
  projectRoot?: string,
): [null | string, string, null | string] {
  try {
    const newCtx = createContextFromPrompt(prompt, projectRoot);
    updateMode(newCtx.id, "active", projectRoot);
    newCtx.mode = "active";
    logInfo("context_selector", `Auto-created context: ${newCtx.id}`);
    return [newCtx.id, "auto_created", formatContextCreated(newCtx)];
  } catch (error: unknown) {
    logError("context_selector", `Primary context creation failed: ${error}`);
    try {
      const now = new Date();
      const yy = String(now.getFullYear()).slice(2);
      const mm = String(now.getMonth() + 1).padStart(2, "0");
      const dd = String(now.getDate()).padStart(2, "0");
      const hh = String(now.getHours()).padStart(2, "0");
      const min = String(now.getMinutes()).padStart(2, "0");
      const fallbackId = `${yy}${mm}${dd}-${hh}${min}-context`;
      const newCtx = createContext(
        fallbackId,
        prompt.trim().slice(0, 200) || "New context",
        "auto-created-fallback",
        projectRoot,
        ["auto-created", "fallback"],
      );
      updateMode(newCtx.id, "active", projectRoot);
      newCtx.mode = "active";
      logInfo("context_selector", `Fallback context created: ${newCtx.id}`);
      return [newCtx.id, "auto_created_fallback", formatContextCreated(newCtx)];
    } catch (error: unknown) {
      logError("context_selector", `ALL context creation failed: ${error}`);
      return [null, "creation_failed", null];
    }
  }
}

// ---------------------------------------------------------------------------
// Caret command handler
// ---------------------------------------------------------------------------

function handleCaretCommand(
  prompt: string,
  contexts: ContextState[],
  projectRoot?: string,
): [null | string, string, null | string] {
  if (contexts.length === 0) {
    const match = prompt.match(/^\^(\S+)(?:\s+(.*))?$/s);
    if (!match) {
      throw new BlockRequest(
        "Invalid prefix. Use ^0 <description> to create a new context.\n" +
        "Example: ^0 implement user authentication system",
      );
    }

    const prefixValue = match[1]!;
    const remaining = match[2] ?? "";
    if (!/^\d+$/.test(prefixValue) || Number.parseInt(prefixValue, 10) !== 0) {
      throw new BlockRequest(
        "No existing contexts to select. Use ^0 <description> to create a new context.\n" +
        "Example: ^0 implement user authentication system",
      );
    }

    const description = remaining.trim();
    if (description.length < MIN_NEW_CONTEXT_CHARS) {
      throw new BlockRequest(
        `Please provide a longer description for your new context.\n` +
        `Your description '${description}' is only ${description.length} characters.\n` +
        `Minimum required: ${MIN_NEW_CONTEXT_CHARS} characters.\n` +
        `Example: ^0 implement user authentication with JWT tokens`,
      );
    }

    return createNewContext(description, projectRoot);
  }

  const [cmd, error] = parseChainedCaret(prompt, contexts);
  if (error) throw new BlockRequest(error + "\n" + formatContextPickerStderr(contexts));
  if (!cmd) throw new BlockRequest(formatContextPickerStderr(contexts));

  const endedContexts: ContextState[] = [];
  for (const ctxId of cmd.ends) {
    const ctxToEnd = contexts.find(c => c.id === ctxId);
    if (!ctxToEnd) {
      throw new BlockRequest(`Context '${ctxId}' no longer exists.\n` + formatContextPickerStderr(contexts));
    }

    completeContext(ctxToEnd.id, projectRoot);
    endedContexts.push(ctxToEnd);
    logInfo("context_selector", `Ended context: ${ctxToEnd.id}`);
  }

  if (cmd.newContextDesc) {
    const [ctxId, method, output] = createNewContext(cmd.newContextDesc, projectRoot);
    if (ctxId && endedContexts.length > 0) {
      const newCtx = getContext(ctxId, projectRoot);
      const feedback = formatCommandFeedback(endedContexts, newCtx);
      return [ctxId, method === "creation_failed" ? method : "caret_new", feedback];
    }

    return [ctxId, method === "creation_failed" ? method : "caret_new", output];
  }

  if (cmd.select) {
    const selectedCtx = contexts.find(c => c.id === cmd.select);
    if (!selectedCtx) {
      throw new BlockRequest(`Context '${cmd.select}' no longer exists.\n` + formatContextPickerStderr(contexts));
    }

    logInfo("context_selector", `Caret-selected context: ${selectedCtx.id}`);
    return [selectedCtx.id, "caret_select", formatCommandFeedback(endedContexts, selectedCtx)];
  }

  if (endedContexts.length > 0) {
    const remainingContexts = getAllContexts("active", projectRoot);
    const feedback = formatCommandFeedback(endedContexts, null);
    if (remainingContexts.length === 0) {
      throw new BlockRequest(
        feedback + "\nAll contexts have been ended. No context selected.\n\n" +
        "Just type your task to start a new context.\n" +
        "Example: implement user authentication system",
      );
    }

    throw new BlockRequest(
      feedback + "\nNo context selected.\n\nSelect a context to continue:\n" +
      formatContextPickerStderr(remainingContexts),
    );
  }

  throw new BlockRequest(formatContextPickerStderr(contexts));
}

// ---------------------------------------------------------------------------
// Main entry point
// ---------------------------------------------------------------------------

/**
 * Determine which context this prompt belongs to.
 * See SPEC.md §8.5
 *
 * Returns [contextId, method, outputText].
 * Throws BlockRequest when request should be blocked to show picker.
 */
export function determineContext(
  prompt: string,
  sessionId?: string,
  projectRoot?: string,
): [null | string, string, null | string] {
  if (isInternalCall()) {
    logDebug("context_selector", "Skipping: internal subprocess call");
    return [null, "skip_internal", null];
  }

  // --- Case 1: session_match ---
  if (sessionId) {
    const sessionContext = getContextBySessionId(sessionId, projectRoot);
    if (sessionContext) {
      logInfo("context_selector", `Session match: ${sessionContext.id}`);
      return [
        sessionContext.id,
        "session_match",
        formatActiveContextReminder(sessionContext, projectRoot),
      ];
    }
  }

  // --- Case 2: caret_command ---
  if (prompt.trim() === "^") {
    const contexts = getAllContexts("active", projectRoot);
    if (contexts.length === 0) {
      throw new BlockRequest(
        "No contexts exist.\n\nJust type your task to start a new context.\n" +
        "Example: implement user authentication system",
      );
    }

    throw new BlockRequest(formatContextPickerStderr(contexts));
  }

  if (prompt.startsWith("^")) {
    const contexts = getAllContexts("active", projectRoot);
    return handleCaretCommand(prompt, contexts, projectRoot);
  }

  // --- Case 3: Staged work match (CHANGED: unified mode) ---
  const stagedContexts = getAllContexts("active", projectRoot).filter(
    (c) => c.mode === "hasStagedWork",
  );

  if (stagedContexts.length > 0) {
    // Separate by artifact type
    const planContexts = stagedContexts.filter(
      (c) => determineArtifactType(c) === "plan",
    );
    const handoffContexts = stagedContexts.filter(
      (c) => determineArtifactType(c) === "handoff",
    );

    // Try plan matching first (content-based matching)
    if (planContexts.length > 0) {
      const matched = matchPlanContent(prompt, planContexts);
      if (matched) {
        if (sessionId) bindSession(matched.id, sessionId, projectRoot);
        updateMode(matched.id, "active", projectRoot, {
          workConsumed: true, // CHANGED: unified flag
          ...(matched.planHash ? {planHashConsumed: matched.planHash} : {}),
        });
        matched.mode = "active";
        logInfo("context_selector", `Plan match (fallback): ${matched.id}`);
        return [
          matched.id,
          "plan_content_match",
          formatPlanContinuation(matched, projectRoot),
        ];
      }
    }

    // Fallback to handoff (pick first - no content matching)
    if (handoffContexts.length > 0) {
      const target = handoffContexts[0]!;
      if (sessionId) bindSession(target.id, sessionId, projectRoot);
      updateMode(target.id, "active", projectRoot, { workConsumed: true }); // CHANGED
      target.mode = "active";
      logInfo("context_selector", `Handoff match (fallback): ${target.id}`);
      return [
        target.id,
        "handoff_match",
        formatHandoffContinuation(target, projectRoot),
      ];
    }
  }

  // --- Case 4: default ---
  return createNewContext(prompt, projectRoot);
}

/**
 * Context store — 2-layer CRUD for context state management.
 * See SPEC.md §7
 *
 * Replaces context_manager's 3-layer approach with a simpler 2-layer model:
 *   state.json   (per context folder — SOURCE OF TRUTH)
 *   index.json   (at _output/ root — fast session→context lookup)
 */

import * as fs from "node:fs";
import path from "node:path";

import { atomicWrite } from "../runtime/atomic-write.js";
import {
  getArchiveContextDir,
  getArchiveDir,
  getArchiveIndexPath,
  getContextDir,
  getContextsDir,
  getIndexPath,
  validateContextId,
} from "../runtime/constants.js";
import { logError, logInfo, logWarn, setContextPath } from "../runtime/logger.js";
import { readStateJson, writeStateJson } from "../runtime/state-io.js";
import { generateContextId, nowIso } from "../runtime/utils.js";
import type { ContextState, IndexEntry, IndexFile, Mode } from "../types.js";

const INDEX_VERSION = "3.0";

// ---------------------------------------------------------------------------
// Public utilities
// ---------------------------------------------------------------------------

/**
 * Determine artifact type from context state.
 * Checks explicit nextArtifactType field first, falls back to field detection.
 *
 * Edge cases:
 * - Both artifacts exist: Log warning, return "plan" (deterministic fallback for corrupted state)
 * - No artifacts: Return null (caller handles gracefully)
 */
export function determineArtifactType(
  state: ContextState,
): "handoff" | "plan" | null {
  // Explicit field takes precedence
  if (state.nextArtifactType) {
    return state.nextArtifactType;
  }

  // Implicit detection
  const hasPlan = Boolean(state.planPath && state.planHash);
  const hasHandoff = Boolean(state.handoffPath);

  // Edge case: Both exist (shouldn't happen - indicates bug in replacement logic)
  // Fallback: Pick plan (deterministic, no filesystem I/O)
  if (hasPlan && hasHandoff) {
    logWarn(
      "context_store",
      `Context ${state.id} has both plan and handoff - indicates bug in replacement logic`,
    );
    return "plan";
  }

  if (hasPlan) return "plan";
  if (hasHandoff) return "handoff";

  // No artifacts present - return null (caller logs warning and skips)
  return null;
}

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

function loadIndex(projectRoot?: string): IndexFile {
  const indexPath = getIndexPath(projectRoot);
  if (fs.existsSync(indexPath)) {
    try {
      const raw = fs.readFileSync(indexPath, "utf8");
      return JSON.parse(raw) as IndexFile;
    } catch (error: unknown) {
      logWarn("context_store", `Failed to read index, recreating: ${error}`);
    }
  }

  return { version: INDEX_VERSION, updatedAt: nowIso(), sessions: {}, contexts: {} };
}

function saveIndex(index: IndexFile, projectRoot?: string): boolean {
  index.updatedAt = nowIso();
  const content = JSON.stringify(index, null, 2);
  const [success, error] = atomicWrite(getIndexPath(projectRoot), content);
  if (!success) {
    logWarn("context_store", `Failed to write index: ${error}`);
  }

  return success;
}

function toIndexEntry(state: ContextState): IndexEntry {
  return {
    summary: state.summary,
    mode: state.mode,
    lastActive: state.lastActive,
  };
}

/**
 * Backward compat: read legacy context.json and convert to ContextState.
 */
function migrateContextJson(contextId: string, projectRoot?: string): ContextState | null {
  const legacyPath = path.join(getContextDir(contextId, projectRoot), "context.json");
  if (!fs.existsSync(legacyPath)) return null;

  try {
    const data = JSON.parse(fs.readFileSync(legacyPath, "utf8"));
    const inFlight = data.in_flight ?? {};
    const oldMode = inFlight.mode ?? "none";
    const MODE_MIGRATION: Record<string, string> = {
      none: "idle",
      planning: "idle",
      pendingImplementation: "has_plan",
      implementing: "active",
    };
    const mode = (MODE_MIGRATION[oldMode] ?? "idle") as Mode;

    const sessionIds: string[] = inFlight.sessionIds ??
      (inFlight.sessionId ? [inFlight.sessionId] : []);

    return {
      id: data.id ?? contextId,
      status: data.status ?? "active",
      summary: data.summary ?? "",
      method: data.method ?? "",
      tags: data.tags ?? [],
      createdAt: data.createdAt ?? "",
      lastActive: data.lastActive ?? "",
      mode,
      planPath: inFlight.artifact_path ?? null,
      planHash: inFlight.artifact_hash ?? null,
      planSignature: null,
      planId: null,
      planAnchors: [],
      planHashConsumed: null,
      planConsumed: false,
      handoffPath: inFlight.handoffPath ?? null,
      handoffConsumed: false,
      workConsumed: false,
      nextArtifactType: null,
      sessionIds,
      lastSession: null,
      tasks: [],
    };
  } catch (error: unknown) {
    logWarn("context_store", `Failed to migrate context.json for '${contextId}': ${error}`);
    return null;
  }
}

// ---------------------------------------------------------------------------
// Core CRUD
// ---------------------------------------------------------------------------

/**
 * Read state.json for a context. Falls back to context.json for migration.
 * See SPEC.md §7.2
 */
export function loadState(contextId: string, projectRoot?: string): ContextState | null {
  const state = readStateJson(contextId, projectRoot);
  if (state) return state;

  // Backward compat: migrate from legacy context.json
  return migrateContextJson(contextId, projectRoot);
}

/**
 * Atomically write state.json AND update index.json.
 * See SPEC.md §7.3
 */
export function saveState(
  contextId: string,
  state: ContextState,
  projectRoot?: string,
): [boolean, null | string] {
  // Ensure the state ID matches
  state.id = contextId;

  const [success, error] = writeStateJson(contextId, state, projectRoot);
  if (!success) {
    logWarn("context_store", `Failed to write state.json for '${contextId}': ${error}`);
    return [false, error];
  }

  // Update index.json
  const index = loadIndex(projectRoot);
  index.contexts[contextId] = toIndexEntry(state);
  // Keep session mappings in sync
  for (const sid of state.sessionIds) {
    if (!index.sessions) index.sessions = {} as Record<string, string>;
    index.sessions[sid] = contextId;
  }

  const indexOk = saveIndex(index, projectRoot);
  if (!indexOk) {
    return [true, "state.json saved but index.json update failed"];
  }

  return [true, null];
}

/**
 * Create a new context folder + state.json + index entry.
 * Throws ValueError-equivalent if context already exists.
 * See SPEC.md §7.4
 */
export function createContext(
  contextId: null | string,
  summary: string,
  method = "",
  projectRoot?: string,
  tags?: string[],
): ContextState {
  // Generate ID if needed
  if (!contextId) {
    const existingIds = new Set<string>();
    const contextsDir = getContextsDir(projectRoot);
    if (fs.existsSync(contextsDir)) {
      for (const entry of fs.readdirSync(contextsDir)) {
        const fullPath = path.join(contextsDir, entry);
        try {
          if (fs.statSync(fullPath).isDirectory()) {
            existingIds.add(entry);
          }
        } catch { /* ignore */ }
      }
    }

    contextId = generateContextId(summary, existingIds);
  }

  contextId = validateContextId(contextId);
  const contextDir = getContextDir(contextId, projectRoot);

  if (fs.existsSync(contextDir)) {
    throw new Error(`Context '${contextId}' already exists`);
  }

  fs.mkdirSync(contextDir, { recursive: true });
  fs.mkdirSync(path.join(contextDir, "notes"), { recursive: true });

  const now = nowIso();
  const state: ContextState = {
    id: contextId,
    status: "active",
    summary,
    method,
    tags: tags ?? [],
    createdAt: now,
    lastActive: now,
    mode: "idle",
    planPath: null,
    planHash: null,
    planSignature: null,
    planId: null,
    planAnchors: [],
    planHashConsumed: null,
    handoffPath: null,
    workConsumed: false, // CHANGED: unified flag
    nextArtifactType: null,
    sessionIds: [],
    lastSession: null,
    tasks: [],
  };

  saveState(contextId, state, projectRoot);
  logInfo("context_store", `Created context: ${contextId}`);
  return state;
}

/**
 * Load a single context by ID.
 * See SPEC.md §7.5
 */
export function getContext(contextId: string, projectRoot?: string): ContextState | null {
  try {
    contextId = validateContextId(contextId);
  } catch {
    return null;
  }

  return loadState(contextId, projectRoot);
}

/**
 * List contexts from index.json, loading each state.json.
 * Falls back to scanning context folders if index is missing.
 * Results sorted by lastActive descending.
 * See SPEC.md §7.6
 */
export function getAllContexts(
  status?: string,
  projectRoot?: string,
): ContextState[] {
  const results: ContextState[] = [];
  const contextsDir = getContextsDir(projectRoot);
  if (!fs.existsSync(contextsDir)) return [];

  // Try index-driven path first
  const index = loadIndex(projectRoot);
  const ctxMap = index.contexts;

  if (ctxMap && typeof ctxMap === "object" && Object.keys(ctxMap).length > 0) {
    for (const cid of Object.keys(ctxMap)) {
      const state = loadState(cid, projectRoot);
      if (state && (!status || state.status === status)) {
        results.push(state);
      }
    }
  } else {
    // Fallback: scan folders
    try {
      for (const entry of fs.readdirSync(contextsDir)) {
        if (entry.startsWith("_")) continue;
        const fullPath = path.join(contextsDir, entry);
        try {
          if (!fs.statSync(fullPath).isDirectory()) continue;
        } catch { continue; }

        const state = loadState(entry, projectRoot);
        if (state && (!status || state.status === status)) {
          results.push(state);
        }
      }
    } catch { /* empty dir */ }
  }

  results.sort((a, b) => (b.lastActive || "").localeCompare(a.lastActive || ""));
  return results;
}

/**
 * Update allowed metadata fields (summary, tags, method) on a context.
 * See SPEC.md §7.7
 */
export function updateContext(
  contextId: string,
  updates: Partial<Pick<ContextState, "method" | "summary" | "tags">>,
  projectRoot?: string,
): ContextState | null {
  const state = getContext(contextId, projectRoot);
  if (!state) return null;

  let changed = false;
  if (updates.summary !== undefined) { state.summary = updates.summary; changed = true; }
  if (updates.tags !== undefined) { state.tags = updates.tags; changed = true; }
  if (updates.method !== undefined) { state.method = updates.method; changed = true; }

  if (!changed) return state;

  state.lastActive = nowIso();
  saveState(contextId, state, projectRoot);
  return state;
}

// ---------------------------------------------------------------------------
// Session binding & mode updates
// ---------------------------------------------------------------------------

/**
 * O(1) lookup: check index.json sessions map first.
 * Side effect: sets logger context path for per-context log routing.
 * See SPEC.md §7.8
 */
export function getContextBySessionId(
  sessionId: string,
  projectRoot?: string,
): ContextState | null {
  if (!sessionId || sessionId === "unknown") return null;

  const index = loadIndex(projectRoot);
  const cid = index.sessions?.[sessionId];
  if (cid) {
    const state = loadState(cid, projectRoot);
    if (state) {
      setLoggerContext(state.id, projectRoot);
      return state;
    }
  }

  // Fallback: scan all contexts
  for (const state of getAllContexts("active", projectRoot)) {
    if (state.sessionIds.includes(sessionId)) {
      setLoggerContext(state.id, projectRoot);
      return state;
    }
  }

  return null;
}

function setLoggerContext(contextId: string, projectRoot?: string): void {
  try {
    const ctxDir = getContextDir(contextId, projectRoot);
    if (fs.existsSync(ctxDir)) {
      setContextPath(ctxDir);
    }
  } catch {
    // Never crash on logging setup
  }
}

/**
 * Add sessionId to both index.json sessions map and state.json sessionIds.
 * See SPEC.md §7.9
 */
export function bindSession(
  contextId: string,
  sessionId: string,
  projectRoot?: string,
): boolean {
  if (!sessionId || sessionId === "unknown") return false;

  const state = getContext(contextId, projectRoot);
  if (!state) return false;

  if (!state.sessionIds.includes(sessionId)) {
    state.sessionIds.push(sessionId);
  }

  state.lastActive = nowIso();

  const [success] = saveState(contextId, state, projectRoot);
  return success;
}

/**
 * Change the mode field, optionally setting plan/handoff fields.
 * See SPEC.md §7.10
 */
export function updateMode(
  contextId: string,
  mode: Mode,
  projectRoot?: string,
  opts?: {
    planAnchors?: string[];
    planHash?: string;
    planHashConsumed?: string;
    planId?: string;
    planPath?: string;
    planSignature?: string;
    workConsumed?: boolean; // FIXED: unified flag (was planConsumed/handoffConsumed)
  },
): ContextState | null {
  const state = getContext(contextId, projectRoot);
  if (!state) return null;

  state.mode = mode;
  state.lastActive = nowIso();

  if (opts) {
    if (opts.planPath !== undefined) state.planPath = opts.planPath;
    if (opts.planHash !== undefined) state.planHash = opts.planHash;
    if (opts.planSignature !== undefined) state.planSignature = opts.planSignature;
    if (opts.planId !== undefined) state.planId = opts.planId;
    if (opts.planAnchors !== undefined) state.planAnchors = opts.planAnchors;
    if (opts.workConsumed !== undefined) state.workConsumed = opts.workConsumed; // CHANGED: unified flag
    if (opts.planHashConsumed !== undefined)
      state.planHashConsumed = opts.planHashConsumed;
  }

  // Clear plan/handoff fields when returning to idle
  if (mode === "idle") {
    state.planPath = null;
    state.planHash = null;
    state.planSignature = null;
    state.planId = null;
    state.planAnchors = [];
    state.planHashConsumed = null;
    state.handoffPath = null;
    state.workConsumed = false; // CHANGED: unified flag
    state.nextArtifactType = null;
  }

  saveState(contextId, state, projectRoot);
  return state;
}

/**
 * Transition idle/hasStagedWork → active, unless in plan mode.
 * See SPEC.md §7.11
 */
export function maybeActivate(
  contextId: string,
  permissionMode: string,
  projectRoot?: string,
  caller = "",
): boolean {
  if (permissionMode === "plan") return false;

  const state = getContext(contextId, projectRoot);
  if (!state) return false;

  if (state.mode === "idle" || state.mode === "hasStagedWork") {
    const oldMode = state.mode;
    const opts: Record<string, unknown> = {};
    if (oldMode === "hasStagedWork") opts.workConsumed = true; // CHANGED: unified flag
    updateMode(contextId, "active", projectRoot, opts);
    logInfo(
      "context_store",
      `maybe_activate (${caller}): ${contextId} ${oldMode} -> active`,
    );
    return true;
  }

  return false;
}

// ---------------------------------------------------------------------------
// Lifecycle
// ---------------------------------------------------------------------------

/**
 * Mark context completed and archive it.
 * See SPEC.md §7.12
 */
export function completeContext(contextId: string, projectRoot?: string): ContextState | null {
  const state = getContext(contextId, projectRoot);
  if (!state) return null;

  if (state.status === "completed") {
    logInfo("context_store", `Context '${contextId}' already completed`);
    return state;
  }

  state.status = "completed";
  state.lastActive = nowIso();
  saveState(contextId, state, projectRoot);
  logInfo("context_store", `Completed context: ${contextId}`);

  const archived = archiveContext(contextId, projectRoot);
  return archived ?? state;
}

/**
 * Move completed context folder to _archive/, update indices.
 * See SPEC.md §7.13
 */
export function archiveContext(contextId: string, projectRoot?: string): ContextState | null {
  const state = getContext(contextId, projectRoot);
  if (!state) {
    logWarn("context_store", `Cannot archive: context '${contextId}' not found`);
    return null;
  }

  if (state.status !== "completed") {
    logWarn("context_store", `Cannot archive: context '${contextId}' not completed`);
    return null;
  }

  const sourceDir = getContextDir(contextId, projectRoot);
  const archiveDest = getArchiveContextDir(contextId, projectRoot);

  if (fs.existsSync(archiveDest)) {
    logWarn("context_store", `Cannot archive: archive folder already exists for '${contextId}'`);
    return null;
  }

  const archiveParent = path.dirname(archiveDest);
  fs.mkdirSync(archiveParent, { recursive: true });

  try {
    fs.renameSync(sourceDir, archiveDest);
  } catch (error: unknown) {
    logError("context_store", `Failed to move context to archive: ${error}`);
    return null;
  }

  // Remove from main index
  const index = loadIndex(projectRoot);
  delete index.contexts[contextId];
  const sessions = index.sessions ?? {};
  for (const [sid, cid] of Object.entries(sessions)) {
    if (cid === contextId) delete sessions[sid];
  }

  saveIndex(index, projectRoot);

  // Add to archive index
  updateArchiveIndex(state, projectRoot);

  logInfo("context_store", `Archived context: ${contextId}`);
  return state;
}

/**
 * Reopen a completed/archived context.
 * See SPEC.md §7.14
 */
export function reopenContext(contextId: string, projectRoot?: string): ContextState | null {
  let state = getContext(contextId, projectRoot);

  if (!state) {
    state = restoreFromArchive(contextId, projectRoot);
  }

  if (!state) return null;

  if (state.status === "active") {
    logInfo("context_store", `Context '${contextId}' already active`);
    return state;
  }

  state.status = "active";
  state.lastActive = nowIso();
  saveState(contextId, state, projectRoot);
  logInfo("context_store", `Reopened context: ${contextId}`);
  return state;
}

// ---------------------------------------------------------------------------
// Auto-creation from prompt
// ---------------------------------------------------------------------------

/**
 * Auto-create a context from the user's prompt.
 * See SPEC.md §7.15
 */
export function createContextFromPrompt(
  userPrompt: string,
  projectRoot?: string,
): ContextState {
  let summary = userPrompt.trim().slice(0, 2000);
  if (userPrompt.trim().length > 2000) {
    summary += "...";
  }

  return createContext(
    null,
    summary,
    "auto-created",
    projectRoot,
    ["auto-created"],
  );
}


// ---------------------------------------------------------------------------
// Archive helpers
// ---------------------------------------------------------------------------

function updateArchiveIndex(state: ContextState, projectRoot?: string): boolean {
  const archiveDir = getArchiveDir(projectRoot);
  const archiveIndexPath = getArchiveIndexPath(projectRoot);
  fs.mkdirSync(archiveDir, { recursive: true });

  let archiveIndex: IndexFile = {
    version: INDEX_VERSION,
    updatedAt: nowIso(),
    sessions: {},
    contexts: {},
  };

  if (fs.existsSync(archiveIndexPath)) {
    try {
      archiveIndex = JSON.parse(fs.readFileSync(archiveIndexPath, "utf8"));
    } catch (error_: unknown) {
      logWarn("context_store", `Failed to read archive index, recreating: ${error_}`);
    }
  }

  archiveIndex.contexts[state.id] = toIndexEntry(state);
  archiveIndex.updatedAt = nowIso();

  const content = JSON.stringify(archiveIndex, null, 2);
  const [success, error] = atomicWrite(archiveIndexPath, content);
  if (!success) {
    logWarn("context_store", `Failed to write archive index: ${error}`);
  }

  return success;
}

function restoreFromArchive(contextId: string, projectRoot?: string): ContextState | null {
  const archiveDir = getArchiveContextDir(contextId, projectRoot);
  const activeDir = getContextDir(contextId, projectRoot);

  if (!fs.existsSync(archiveDir)) return null;
  if (fs.existsSync(activeDir)) {
    logWarn("context_store", `Cannot restore: active folder already exists for '${contextId}'`);
    return null;
  }

  try {
    fs.renameSync(archiveDir, activeDir);
  } catch (error: unknown) {
    logError("context_store", `Failed to restore context from archive: ${error}`);
    return null;
  }

  // Remove from archive index
  removeFromArchiveIndex(contextId, projectRoot);

  const state = loadState(contextId, projectRoot);
  logInfo("context_store", `Restored context from archive: ${contextId}`);
  return state;
}

function removeFromArchiveIndex(contextId: string, projectRoot?: string): boolean {
  const archiveIndexPath = getArchiveIndexPath(projectRoot);
  if (!fs.existsSync(archiveIndexPath)) return true;

  try {
    const archiveIndex = JSON.parse(fs.readFileSync(archiveIndexPath, "utf8")) as IndexFile;
    if (archiveIndex.contexts[contextId]) {
      delete archiveIndex.contexts[contextId];
      archiveIndex.updatedAt = nowIso();
      const content = JSON.stringify(archiveIndex, null, 2);
      const [success, error] = atomicWrite(archiveIndexPath, content);
      if (!success) {
        logWarn("context_store", `Failed to write archive index: ${error}`);
        return false;
      }
    }

    return true;
  } catch (error: unknown) {
    logWarn("context_store", `Failed to read archive index: ${error}`);
    return false;
  }
}

/**
 * Plan lifecycle management — archival, lookup, and path extraction.
 * See SPEC.md §9
 *
 * Provides pure-data operations on plan files:
 * - archivePlan: copy plan to context plans/ folder, compute hash + signature
 * - findLatestPlan: locate the most relevant plan for a context
 * - extractPlanPathFromResult: parse plan path from ExitPlanMode output
 */

import * as crypto from "node:crypto";
import * as fs from "node:fs";
import path from "node:path";

import { atomicWrite } from "../runtime/atomic-write.js";
import { getContextPlansDir, sanitizeTitle } from "../runtime/constants.js";
import { logDebug, logError, logInfo, logWarn } from "../runtime/logger.js";
import { generateSlug } from "../runtime/utils.js";

// ---------------------------------------------------------------------------
// Plan archival
// ---------------------------------------------------------------------------

/**
 * Archive a plan file to the context's plans/ folder.
 * Computes a content hash and signature.
 * Does NOT modify state.json or mode.
 * See SPEC.md §9.2
 *
 * Returns [archivedPath, planHash, planSignature] on success,
 * or [null, null, null] on error.
 */
export function archivePlan(
  planPath: string,
  contextId: string,
  projectRoot?: string,
): [null | string, null | string, null | string] {
  if (!fs.existsSync(planPath)) {
    logWarn("plan_manager", `Plan file not found: ${planPath}`);
    return [null, null, null];
  }

  let content: string;
  try {
    content = fs.readFileSync(planPath, "utf8");
  } catch (error_: unknown) {
    logError("plan_manager", `Failed to read plan: ${error_}`);
    return [null, null, null];
  }

  // Compute hash and signature
  const planHash = crypto.createHash("sha256").update(content, "utf8").digest("hex").slice(0, 12);
  const planSignature = content.slice(0, 200);

  // Ensure plans directory exists
  const plansDir = getContextPlansDir(contextId, projectRoot);
  fs.mkdirSync(plansDir, { recursive: true });

  // Generate archive filename: YYYY-MM-DD-HHMM-<slug>.md
  const now = new Date();
  const dateStr = [
    now.getFullYear(),
    "-",
    String(now.getMonth() + 1).padStart(2, "0"),
    "-",
    String(now.getDate()).padStart(2, "0"),
    "-",
    String(now.getHours()).padStart(2, "0"),
    String(now.getMinutes()).padStart(2, "0"),
  ].join("");

  // Extract a clean summary from plan content for slug generation.
  // Headings describe the plan's intent better than raw markdown body.
  const summary = extractPlanSummary(content);
  const slug = generateSlug(summary, 60, sanitizeTitle(
    path.basename(planPath, path.extname(planPath)), 30,
  ));

  let archiveName = `${dateStr}-${slug}.md`;
  let archivePath = path.join(plansDir, archiveName);

  // Handle filename collisions
  let counter = 2;
  while (fs.existsSync(archivePath)) {
    archiveName = `${dateStr}-${slug}-${counter}.md`;
    archivePath = path.join(plansDir, archiveName);
    counter++;
  }

  // Write archived plan atomically
  const [success, error] = atomicWrite(archivePath, content);
  if (!success) {
    logError("plan_manager", `Failed to write archive: ${error}`);
    return [null, null, null];
  }

  logInfo("plan_manager", `Archived plan to: ${archivePath}`);
  return [archivePath, planHash, planSignature];
}

/**
 * Extract a human-readable summary from plan markdown content.
 * Pulls headings and the first substantial paragraph, producing
 * text suitable for the AI slug generator (which expects conversational input).
 */
function extractPlanSummary(content: string): string {
  const lines = content.split(/\r?\n/);
  const parts: string[] = [];
  let firstParagraph = "";

  for (const line of lines) {
    const trimmed = line.trim();
    // Collect markdown headings (strip # prefix)
    if (trimmed.startsWith("#")) {
      const heading = trimmed.replace(/^#+\s*/, "");
      if (heading.length > 2) parts.push(heading);
    }

    // Grab first substantial non-heading line as context
    if (!firstParagraph && !trimmed.startsWith("#") && trimmed.length > 20) {
      firstParagraph = trimmed.slice(0, 120);
    }

    // Enough material for the AI
    if (parts.length >= 5) break;
  }

  if (firstParagraph) parts.push(firstParagraph);
  return parts.join(" ").slice(0, 500) || content.slice(0, 500);
}

// ---------------------------------------------------------------------------
// Plan lookup
// ---------------------------------------------------------------------------

/**
 * Find the most relevant plan file for a context.
 * Priority: state.json planPath > most recent .md in plans/ dir.
 * See SPEC.md §9.3
 */
export function findLatestPlan(
  contextId: string,
  projectRoot?: string,
): null | string {
  // 1. Check state.json planPath first
  try {
    // Dynamic import to avoid circular dependency at module level
    // eslint-disable-next-line @typescript-eslint/no-require-imports, no-undef -- dynamic require to avoid circular dependency
    const stateIo = require("../runtime/state-io.js");
    const state = stateIo.readStateJson(contextId, projectRoot);
    if (state?.planPath && fs.existsSync(state.planPath)) {
      return state.planPath;
    }
  } catch (error: unknown) {
    logWarn("plan_manager", `Failed to check state.json planPath: ${error}`);
  }

  // 2. Fall back to most recent .md in plans/ dir
  const plansDir = getContextPlansDir(contextId, projectRoot);
  if (fs.existsSync(plansDir)) {
    try {
      const files = fs.readdirSync(plansDir)
        .filter(f => f.endsWith(".md"))
        .map(f => {
          const fullPath = path.join(plansDir, f);
          return { path: fullPath, mtime: fs.statSync(fullPath).mtimeMs };
        })
        .sort((a, b) => b.mtime - a.mtime);

      if (files.length > 0) {
        return files[0]!.path;
      }
    } catch { /* ignore */ }
  }

  return null;
}

// ---------------------------------------------------------------------------
// Plan identification and normalization
// ---------------------------------------------------------------------------

/**
 * Generate a short unique plan identifier (8 hex chars).
 * See SPEC.md §9.4
 */
export function generatePlanId(): string {
  return crypto.randomUUID().replaceAll('-', "").slice(0, 8);
}

/**
 * Aggressively normalize plan content for hashing.
 * Strips all XML/HTML tags and collapses whitespace.
 * See SPEC.md §9.5
 */
export function normalizePlanContent(text: string): string {
  let result = text.replaceAll(/<[^>]+>/g, "");
  result = result.replaceAll(/\s+/g, " ").trim();
  return result;
}

/**
 * Extract structural anchors from plan content.
 * Returns markdown headings + first substantial paragraph as short strings.
 * See SPEC.md §9.6
 */
export function extractPlanAnchors(content: string, maxAnchors = 5): string[] {
  const anchors: string[] = [];
  for (const line of content.split(/\r?\n/)) {
    const trimmed = line.trim();
    if (trimmed.startsWith("#") && trimmed.length > 3) {
      anchors.push(trimmed.slice(0, 80));
    } else if (anchors.length === 0 && trimmed.length > 20) {
      anchors.push(trimmed.slice(0, 80));
    }

    if (anchors.length >= maxAnchors) break;
  }

  return anchors;
}

// ---------------------------------------------------------------------------
// Transcript-based plan path extraction
// ---------------------------------------------------------------------------

const MAX_TRANSCRIPT_SIZE = 50 * 1024 * 1024; // 50 MB

/**
 * Find the plan file path by parsing the session transcript JSONL.
 * Searches in reverse for the most recent Write tool call targeting .claude/plans/.
 * See SPEC.md §9.7
 */
export function findPlanPathInTranscript(transcriptPath: string): null | string {
  if (!transcriptPath) return null;

  if (!fs.existsSync(transcriptPath)) {
    logDebug("plan_manager", `Transcript not found: ${transcriptPath}`);
    return null;
  }

  let size: number;
  try {
    size = fs.statSync(transcriptPath).size;
  } catch {
    return null;
  }

  if (size > MAX_TRANSCRIPT_SIZE) {
    logWarn("plan_manager", `Transcript too large (${size} bytes), skipping`);
    return null;
  }

  let lines: string[];
  try {
    lines = fs.readFileSync(transcriptPath, "utf8").split(/\r?\n/);
  } catch (error: unknown) {
    logWarn("plan_manager", `Failed to read transcript: ${error}`);
    return null;
  }

  for (let i = lines.length - 1; i >= 0; i--) {
    const line = lines[i]!.trim();
    if (!line) continue;

    let data: unknown;
    try {
      data = JSON.parse(line);
    } catch {
      continue;
    }

    let contentArr: unknown;
    try {
      contentArr = data.message?.content;
    } catch {
      continue;
    }

    if (!Array.isArray(contentArr)) continue;

    for (const block of contentArr) {
      if (typeof block !== "object" || block === null) continue;
      if (block.type !== "tool_use" || block.name !== "Write") continue;

      const filePath = block.input?.file_path;
      if (!filePath) continue;

      // Check if path contains .claude/plans/ as consecutive parts
      const parts = filePath.replaceAll('\\', "/").split("/");
      for (let j = 0; j < parts.length - 1; j++) {
        if (parts[j] === ".claude" && parts[j + 1] === "plans") {
          logInfo("plan_manager", `Extracted plan path from transcript: ${filePath}`);
          return filePath;
        }
      }
    }
  }

  logDebug("plan_manager", "No plan Write found in transcript");
  return null;
}

// ---------------------------------------------------------------------------
// Path extraction from tool output
// ---------------------------------------------------------------------------

/**
 * Extract plan file path from ExitPlanMode tool result.
 * Parses the pattern: "Your plan has been saved to: <path>"
 * See SPEC.md §9.8
 */
export function extractPlanPathFromResult(toolResult: string): null | string {
  if (!toolResult) return null;
  const match = toolResult.match(/Your plan has been saved to:\s*(.+\.md)/);
  return match ? match[1]!.trim() : null;
}

/**
 * Task tracker — direct state.json CRUD for tasks.
 * See SPEC.md §10
 *
 * Writes tasks directly to the tasks[] array in state.json.
 * Uses state-io for I/O to avoid circular imports with context-store.
 */

import { logWarn } from "../runtime/logger.js";
import { readStateJson, writeStateJson } from "../runtime/state-io.js";
import { nowIso } from "../runtime/utils.js";
import type { Task } from "../types.js";

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Scan tasks[] for highest aiw-N, return aiw-(N+1).
 * See SPEC.md §10.2
 */
export function generateNextTaskId(contextId: string, projectRoot?: string): string {
  const state = readStateJson(contextId, projectRoot);
  const tasks = state?.tasks ?? [];

  let maxNum = 0;
  for (const t of tasks) {
    const match = /^aiw-(\d+)$/.exec(t.id);
    if (match) {
      const num = Number.parseInt(match[1]!, 10);
      if (num > maxNum) maxNum = num;
    }
  }

  return `aiw-${maxNum + 1}`;
}

/**
 * Add a new task to state.json tasks[] and return the task object.
 * See SPEC.md §10.3
 */
export function addTask(
  contextId: string,
  subject: string,
  description = "",
  activeForm = "",
  sessionId = "",
  projectRoot?: string,
): null | Task {
  const state = readStateJson(contextId, projectRoot);
  if (!state) return null;

  const taskId = generateNextTaskId(contextId, projectRoot);
  const task: Task = {
    id: taskId,
    subject,
    description,
    activeForm,
    status: "pending",
    createdAt: nowIso(),
    completedAt: null,
    evidence: "",
    workSummary: "",
    filesChanged: [],
    sessionId,
  };

  state.tasks.push(task);
  state.lastActive = nowIso();

  const [success] = writeStateJson(contextId, state, projectRoot);
  return success ? task : null;
}

/**
 * Find task by task_id in tasks[], update fields, return true on success.
 * See SPEC.md §10.4
 */
export function updateTask(
  contextId: string,
  taskId: string,
  opts?: {
    evidence?: string;
    filesChanged?: string[];
    sessionId?: string;
    status?: string;
    workSummary?: string;
  },
  projectRoot?: string,
): boolean {
  const state = readStateJson(contextId, projectRoot);
  if (!state) return false;

  for (const task of state.tasks) {
    if (task.id === taskId) {
      if (opts?.status !== undefined) {
        task.status = opts.status as Task["status"];
        if (opts.status === "completed") {
          task.completedAt = nowIso();
        }
      }

      if (opts?.evidence) task.evidence = opts.evidence;
      if (opts?.workSummary) task.workSummary = opts.workSummary;
      if (opts?.filesChanged !== undefined) task.filesChanged = opts.filesChanged;
      if (opts?.sessionId) task.sessionId = opts.sessionId;
      state.lastActive = nowIso();
      const [success] = writeStateJson(contextId, state, projectRoot);
      return success;
    }
  }

  logWarn("task_tracker", `Task '${taskId}' not found in context '${contextId}'`);
  return false;
}

/**
 * Remove task from tasks[] and return true on success.
 * See SPEC.md §10.5
 */
export function deleteTask(
  contextId: string,
  taskId: string,
  projectRoot?: string,
): boolean {
  const state = readStateJson(contextId, projectRoot);
  if (!state) return false;

  const originalLen = state.tasks.length;
  state.tasks = state.tasks.filter(t => t.id !== taskId);

  if (state.tasks.length === originalLen) {
    logWarn("task_tracker", `Task '${taskId}' not found in context '${contextId}'`);
    return false;
  }

  state.lastActive = nowIso();
  const [success] = writeStateJson(contextId, state, projectRoot);
  return success;
}

/**
 * Return tasks[] from state.json.
 * See SPEC.md §10.6
 */
export function getTasks(contextId: string, projectRoot?: string): Task[] {
  const state = readStateJson(contextId, projectRoot);
  if (!state) return [];
  return state.tasks;
}

/**
 * Partition tasks and format as markdown checklist.
 * See SPEC.md §10.7
 */
export function generateTaskSummary(contextId: string, projectRoot?: string): string {
  const tasks = getTasks(contextId, projectRoot);
  if (tasks.length === 0) return "No tasks in this context.";

  const completed = tasks.filter(t => t.status === "completed");
  const inProgress = tasks.filter(t => t.status === "inProgress");
  const pending = tasks.filter(t => t.status === "pending");
  const blocked = tasks.filter(t => t.status === "blocked");

  const lines: string[] = [`### Tasks (${tasks.length} total)`, ""];

  for (const t of completed) {
    const ws = t.workSummary ? `\n  Work: ${t.workSummary}` : "";
    lines.push(`- [x] ${t.id}: ${t.subject}${ws}`);
  }

  for (const t of inProgress) {
    lines.push(`- [~] ${t.id}: ${t.subject}`);
  }

  for (const t of pending) {
    lines.push(`- [ ] ${t.id}: ${t.subject}`);
  }

  for (const t of blocked) {
    lines.push(`- [!] ${t.id}: ${t.subject}`);
  }

  return lines.join("\n");
}

/**
 * Common utilities for hook scripts.
 * Standardized boilerplate for JSON parsing, validation, error handling.
 * See SPEC.md §5
 */

import * as fs from "node:fs";

import { getContextBySessionId } from "../context/context-store.js";
import { getProjectRoot } from "../runtime/constants.js";
import { getContextPath as _getContextPath,  hookLog,     logDebug, logWarn,  setSessionId } from "../runtime/logger.js";
import type { HookInput, HookOutput, PermissionRequestOutput } from "../types.js";

// Re-export logger functions for convenience (matches Python hook_utils re-exports)


// Context window baseline: tokens not visible in hook data §5.9
export const CONTEXT_BASELINE_TOKENS = 22_600;
export const DEFAULT_CONTEXT_WINDOW_SIZE = 200_000;

// Event metadata stash — populated by loadHookInput(), read by runHook()
let _lastHookEvent: null | string = null;
let _lastToolName: null | string = null;
let _cachedHookName: null | string = null;

// Pre-fetched input stash
let _prefetchedInput: null | Record<string, unknown> = null;

/**
 * Load and parse JSON from stdin (or return prefetched input if set).
 * Returns null if stdin is empty or invalid JSON.
 * See SPEC.md §5.1
 */
export function loadHookInput(): HookInput | null {
  if (_prefetchedInput !== null) {
    const result = _prefetchedInput;
    _prefetchedInput = null; // consume once
    if (result && typeof result === "object") {
      _lastHookEvent = result.hook_event_name ?? null;
      _lastToolName = result.tool_name ?? null;
    }

    return result as HookInput;
  }

  try {
    // Read entire stdin using fd 0 (cross-platform, works on Windows)
    const inputData = fs.readFileSync(0, "utf8").trim();
    if (!inputData) return null;

    const result = JSON.parse(inputData);
    if (result && typeof result === "object") {
      _lastHookEvent = result.hook_event_name ?? null;
      _lastToolName = result.tool_name ?? null;
    }

    return result as HookInput;
  } catch {
    return null;
  }
}

/**
 * Validate hook event type and optional tool name.
 * See SPEC.md §5.2
 */
export function validateHookEvent(
  payload: HookInput,
  expectedEvent: string,
  expectedTool?: string,
): boolean {
  if (payload.hook_event_name !== expectedEvent) return false;
  if (expectedTool && payload.tool_name !== expectedTool) return false;
  return true;
}

/**
 * Extract and validate tool_input from payload.
 * See SPEC.md §5.3
 */
export function getToolInput(
  payload: HookInput,
): null | Record<string, unknown> {
  const toolInput = payload.tool_input;
  return toolInput && typeof toolInput === "object" ? toolInput : null;
}

/**
 * Check if persistence should be skipped based on metadata flags.
 * See SPEC.md §5.4
 */
export function checkSkipPersistence(
  payload: HookInput,
  hookName = "hook",
): boolean {
  const toolInput = getToolInput(payload);
  if (!toolInput) return false;

  const {metadata} = toolInput;
  if (metadata && typeof metadata === "object" && metadata.skip_persistence) {
    logDebug(hookName, "Skipping persistence (skip_persistence flag set)");
    return true;
  }

  return false;
}

/**
 * Emit hookSpecificOutput with additionalContext to stdout.
 * hookEventName is required by Claude Code's Zod validator (discriminated union).
 * Auto-detected from stdin payload (set by loadHookInput/runHook).
 *
 * SubagentStop and Stop events use top-level systemMessage field instead of hookSpecificOutput.
 * See SPEC.md §5.5
 */
export function emitContext(additionalContext: string): void {
  const eventName = _lastHookEvent ?? undefined;
  const tool = _lastToolName;

  // SubagentStop and Stop use top-level systemMessage field
  if (eventName === "SubagentStop" || eventName === "Stop") {
    const out = { systemMessage: additionalContext };
    process.stdout.write(JSON.stringify(out) + "\n");
    _logEmit("systemMessage", additionalContext.length, { event: eventName ?? "unknown", systemMessage: additionalContext });
    return;
  }

  // All other events use hookSpecificOutput
  const out: HookOutput = {
    hookSpecificOutput: {
      ...(eventName ? { hookEventName: eventName } : {}),
      additionalContext,
    },
  };
  const json = JSON.stringify(out);
  const eventDesc = tool ? `${eventName}:${tool}` : eventName ?? "unknown";
  _logEmit("context", additionalContext.length, { event: eventDesc, additionalContext });
  process.stdout.write(json + "\n");
}

/**
 * Emit hookSpecificOutput that denies the tool call with context and reason.
 * hookEventName is required by Claude Code's Zod validator (discriminated union).
 * Auto-detected from stdin payload (set by loadHookInput/runHook).
 * See SPEC.md §5.6
 */
export function emitContextAndBlock(
  additionalContext: string,
  reason: string,
): void {
  const eventName = _lastHookEvent ?? undefined;
  if (eventName && eventName !== "PreToolUse") {
    logWarn(_cachedHookName ?? "unknown",
      `emitContextAndBlock() called from ${eventName} — permissionDecision only works for PreToolUse. ` +
      `Use emitBlock() or the event-specific function instead.`);
  }

  const tool = _lastToolName;
  const out: HookOutput = {
    hookSpecificOutput: {
      ...(eventName ? { hookEventName: eventName } : {}),
      additionalContext,
      permissionDecision: "deny",
      permissionDecisionReason: reason,
    },
  };
  const json = JSON.stringify(out);
  const eventDesc = tool ? `${eventName}:${tool}` : eventName ?? "unknown";
  _logEmit("block", additionalContext.length, { event: eventDesc, additionalContext, blockReason: reason });
  process.stdout.write(json + "\n");
}

/** Log hook output (context, systemMessage, or block) to hook-log.jsonl for visibility. */
function _logEmit(type: "block" | "context" | "systemMessage", chars: number, payload: Record<string, unknown>): void {
  const hook = _cachedHookName ?? "unknown";
  const event = payload.event ?? "unknown";
  const mechanism = payload.mechanism ? ` via ${payload.mechanism}` : "";
  const msg = type === "block"
    ? `HOOK_OUTPUT [${type}] ${event} ${chars} chars${mechanism}, reason="${(payload.blockReason ?? "").slice(0, 80)}"`
    : `HOOK_OUTPUT [${type}] ${event} ${chars} chars`;
  hookLog("info", hook, msg, { data: payload });
}

/**
 * Block a user prompt submission with a reason.
 * Only works for UserPromptSubmit hooks.
 * Output: top-level { decision: "block", reason } + optional hookSpecificOutput.additionalContext
 */
export function emitBlockPrompt(reason: string, context?: string): void {
  const eventName = _lastHookEvent ?? undefined;
  if (eventName && eventName !== "UserPromptSubmit") {
    logWarn(_cachedHookName ?? "unknown",
      `emitBlockPrompt() called from ${eventName} — only works for UserPromptSubmit`);
  }

  const out: HookOutput = {
    decision: "block",
    reason,
    ...(context ? {
      hookSpecificOutput: {
        ...(eventName ? { hookEventName: eventName } : {}),
        additionalContext: context,
      }
    } : {}),
  };
  _logEmit("block", context?.length ?? 0, { event: eventName ?? "unknown", additionalContext: context, blockReason: reason });
  process.stdout.write(JSON.stringify(out) + "\n");
}

/**
 * Block via exit code 2 + stderr feedback.
 * Works for PostToolUse, PostToolUseFailure.
 * The reason becomes the stderr message (fed to Claude as system-reminder).
 * If context is provided, it's prepended to the stderr message for richer feedback.
 * NOTE: Exit 2 causes Claude Code to ignore all JSON stdout — only stderr matters.
 */
export function emitBlockViaExit(reason: string, context?: string): void {
  const stderrMessage = context ? `${context}\n\n${reason}` : reason;
  _logEmit("block", stderrMessage.length, {
    event: _lastHookEvent ?? "unknown",
    blockReason: reason,
    mechanism: "exit2",
  });
  process.stderr.write(stderrMessage + "\n");
  throw new Error("SystemExit:2");
}

/**
 * Block via top-level { decision: "block", reason }.
 * Works for Stop and SubagentStop events.
 * These events do NOT support additionalContext — only reason is available.
 */
export function emitBlockTopLevel(reason: string): void {
  const eventName = _lastHookEvent ?? undefined;
  if (eventName && eventName !== "Stop" && eventName !== "SubagentStop") {
    logWarn(_cachedHookName ?? "unknown",
      `emitBlockTopLevel() called from ${eventName} — only works for Stop/SubagentStop`);
  }

  const out = { decision: "block", reason };
  _logEmit("block", reason.length, {
    event: eventName ?? "unknown",
    blockReason: reason,
    mechanism: "topLevelDecision",
  });
  process.stdout.write(JSON.stringify(out) + "\n");
}

/**
 * Respond to a PermissionRequest with allow/deny.
 * Only works for PermissionRequest hooks.
 */
export function emitPermissionDecision(
  behavior: "allow" | "deny",
  opts?: { message?: string; updatedInput?: Record<string, unknown>; updatedPermissions?: Record<string, unknown> },
): void {
  const out: PermissionRequestOutput = {
    decision: {
      behavior,
      ...(opts?.message ? { message: opts.message } : {}),
      ...(opts?.updatedInput ? { updatedInput: opts.updatedInput } : {}),
      ...(opts?.updatedPermissions ? { updatedPermissions: opts.updatedPermissions } : {}),
    },
  };
  _logEmit("block", 0, {
    event: _lastHookEvent ?? "unknown",
    blockReason: `permission:${behavior}`,
    mechanism: "permissionRequest",
  });
  process.stdout.write(JSON.stringify(out) + "\n");
}

/**
 * Unified block dispatcher — auto-detects the correct blocking mechanism
 * based on the current hook event type.
 *
 * PreToolUse → permissionDecision: "deny" (via emitContextAndBlock)
 * UserPromptSubmit → top-level decision: "block" (via emitBlockPrompt)
 * PostToolUse/PostToolUseFailure → exit(2) + stderr (via emitBlockViaExit)
 * Stop/SubagentStop → top-level { decision: "block", reason } (via emitBlockTopLevel)
 * PermissionRequest → decision: { behavior: "deny" } (via emitPermissionDecision)
 * SessionStart/Notification/SubagentStart/SessionEnd/etc. → warn and no-op
 *
 * This is the RECOMMENDED universal blocking API. Hook authors should use
 * emitBlock() and let the library handle event-specific dispatch.
 */
export function emitBlock(reason: string, context?: string): void {
  const event = _lastHookEvent;
  switch (event) {
    case "PermissionRequest": {
      emitPermissionDecision("deny", { message: reason });
      break;
    }

    case "PostToolUse":
    case "PostToolUseFailure": {
      emitBlockViaExit(reason, context);
      break;
    }

    case "PreToolUse": {
      emitContextAndBlock(context ?? reason, reason);
      break;
    }

    case "Stop":
    case "SubagentStop": {
      emitBlockTopLevel(reason);
      break;
    }

    case "UserPromptSubmit": {
      emitBlockPrompt(reason, context);
      break;
    }

    default: {
      logWarn(_cachedHookName ?? "unknown",
        `emitBlock() called from ${event ?? "unknown"} — no blocking mechanism exists for this event type, ignoring`);
      break;
    }
  }
}

/**
 * Auto-detect template origin from the hook script path.
 */
function detectTemplate(scriptPath = ""): string {
  const p = (scriptPath || (process.argv[1] ?? "")).replaceAll('\\', "/");
  if (p.includes("/_shared/hooks/") || p.startsWith("_shared/hooks/")) {
    return "shared";
  }

  const match = p.match(/_([a-z][a-z0-9-]*)\/hooks\//);
  if (match?.[1]) return match[1]; // e.g., "cc-native"
  return "unknown";
}

/**
 * Parse context window from hook input.
 * Returns [tokensUsed, maxTokens] or [null, null].
 * See SPEC.md §5.9
 */
export function parseContextWindow(
  hookInput: HookInput,
): [null | number, null | number] {
  const contextWindow = hookInput.context_window;
  if (!contextWindow) return [null, null];

  const currentUsage = contextWindow.current_usage;
  if (!currentUsage) return [null, null];

  const cacheRead = currentUsage.cache_read_input_tokens ?? 0;
  const inputTokens = currentUsage.input_tokens ?? 0;
  const cacheCreation = currentUsage.cache_creation_input_tokens ?? 0;
  const outputTokens = currentUsage.output_tokens ?? 0;

  const contentTokens = cacheRead + inputTokens + cacheCreation + outputTokens;
  const tokensUsed = contentTokens + CONTEXT_BASELINE_TOKENS;
  const maxTokens = contextWindow.context_window_size ?? DEFAULT_CONTEXT_WINDOW_SIZE;

  return [tokensUsed, maxTokens];
}

/**
 * Get context percentage remaining with fallback.
 * Returns [percentRemaining, tokensUsed, maxTokens] or [null, null, null].
 * See SPEC.md §5.9
 */
export function getContextPercentRemaining(
  hookInput: HookInput,
): [null | number, null | number, null | number] {
  const [tokensUsed, maxTokens] = parseContextWindow(hookInput);

  if (tokensUsed !== null && maxTokens !== null && maxTokens > 0) {
    const remaining = maxTokens - tokensUsed;
    const percentRemaining = Math.max(
      0,
      Math.min(100, Math.round((remaining / maxTokens) * 100)),
    );
    return [percentRemaining, tokensUsed, maxTokens];
  }

  // Source 2: context.json fallback (written by status_line.py)
  try {
    const {sessionId} = hookInput;
    if (sessionId) {
      const projectRoot = getProjectRoot(hookInput.cwd);
      const context = getContextBySessionId(sessionId, projectRoot);
      if (context?.lastSession?.context_remaining_pct !== undefined) {
        return [context.lastSession.context_remaining_pct, null, null];
      }
    }
  } catch {
    // Fallback failed — degrade gracefully
  }

  return [null, null, null];
}

/**
 * Read stdin early and extract sessionId + event metadata.
 * Stashes parsed input for loadHookInput() to consume later.
 */
function _earlyReadInput(prefetchedInput?: Record<string, unknown>): void {
  if (prefetchedInput !== undefined) {
    _prefetchedInput = prefetchedInput;
  }

  // If we already have prefetched input, extract metadata from it
  if (_prefetchedInput && typeof _prefetchedInput === "object") {
    _lastHookEvent = _prefetchedInput.hook_event_name ?? null;
    _lastToolName = _prefetchedInput.tool_name ?? null;
    if (_prefetchedInput.sessionId) {
      setSessionId(_prefetchedInput.sessionId);
    }

    return;
  }

  // Read stdin now so HOOK_START can include sid
  try {
    const inputData = fs.readFileSync(0, "utf8").trim();
    if (inputData) {
      const parsed = JSON.parse(inputData);
      if (parsed && typeof parsed === "object") {
        _prefetchedInput = parsed;
        _lastHookEvent = parsed.hook_event_name ?? null;
        _lastToolName = parsed.tool_name ?? null;
        if (parsed.sessionId) {
          setSessionId(parsed.sessionId);
        }
      }
    }
  } catch {
    // Non-fatal — loadHookInput will return null
  }
}

/**
 * Standard hook entry point with lifecycle logging.
 * See SPEC.md §5.7
 */
export function runHook(
  mainFunc: () => number | void,
  hookName = "unknown",
  prefetchedInput?: Record<string, unknown>,
): void {
  _earlyReadInput(prefetchedInput);
  _cachedHookName = hookName;

  // Ensure cwd is project root so relative paths in hooks resolve correctly,
  // even when cwd has drifted via `cd` in a Bash tool call.
  try {
    const projectRoot = getProjectRoot(_prefetchedInput?.cwd);
    if (process.cwd() !== projectRoot) process.chdir(projectRoot);
  } catch { /* non-fatal — proceed with current cwd */ }

  const startTime = performance.now();
  const template = detectTemplate();
  const event = _lastHookEvent ?? "unknown";
  const tool = _lastToolName;

  const startData: Record<string, unknown> = {
    lifecycle: "start",
    template,
    event,
  };
  if (tool) startData.tool = tool;
  hookLog("info", hookName, "HOOK_START", { data: startData });

  let exitCode = 0;
  let status = "success";
  let errorInfo: [Error, string] | null = null;

  try {
    const result = mainFunc();
    exitCode = typeof result === "number" ? result : 0;
    status = exitCode === 0 ? "success" : "blocked";
  } catch (error: unknown) {
    if (error instanceof Error && error.message.startsWith("SystemExit:")) {
      const code = Number.parseInt(error.message.slice(11), 10);
      exitCode = Number.isNaN(code) ? (error.message.slice(11) ? 1 : 0) : code;
      status = exitCode === 0 ? "success" : "blocked";
    } else {
      exitCode = 0; // Non-blocking
      status = "error";
      const stack = error instanceof Error ? error.stack ?? "" : "";
      errorInfo = [error instanceof Error ? error : new Error(String(error)), stack];
    }
  }

  _emitHookEnd(hookName, startTime, exitCode, status, errorInfo, startData, event, tool, template);
  process.exitCode = exitCode;
}

/**
 * Async variant of runHook for hooks that need await (e.g., AI inference).
 * Provides identical structured JSONL lifecycle logging as runHook.
 * See SPEC.md §5.7
 */
export function runHookAsync(
  mainFunc: () => Promise<number | void>,
  hookName = "unknown",
  prefetchedInput?: Record<string, unknown>,
): void {
  _earlyReadInput(prefetchedInput);
  _cachedHookName = hookName;

  // Ensure cwd is project root so relative paths in hooks resolve correctly,
  // even when cwd has drifted via `cd` in a Bash tool call.
  try {
    const projectRoot = getProjectRoot(_prefetchedInput?.cwd);
    if (process.cwd() !== projectRoot) process.chdir(projectRoot);
  } catch { /* non-fatal — proceed with current cwd */ }

  const startTime = performance.now();
  const template = detectTemplate();
  const event = _lastHookEvent ?? "unknown";
  const tool = _lastToolName;

  const startData: Record<string, unknown> = {
    lifecycle: "start",
    template,
    event,
  };
  if (tool) startData.tool = tool;
  hookLog("info", hookName, "HOOK_START", { data: startData });

  mainFunc()
    .then((result) => {
      const exitCode = typeof result === "number" ? result : 0;
      _emitHookEnd(hookName, startTime, exitCode, exitCode === 0 ? "success" : "blocked", null, startData, event, tool, template);
      _drainAndExit(exitCode);
    })
    .catch((error: unknown) => {
      let exitCode = 0;
      let status = "error";
      let errorInfo: [Error, string] | null = null;

      if (error instanceof Error && error.message.startsWith("SystemExit:")) {
        const code = Number.parseInt(error.message.slice(11), 10);
        exitCode = Number.isNaN(code) ? (error.message.slice(11) ? 1 : 0) : code;
        status = exitCode === 0 ? "success" : "blocked";
      } else {
        exitCode = 0; // Non-blocking (fail open)
        const stack = error instanceof Error ? error.stack ?? "" : "";
        errorInfo = [error instanceof Error ? error : new Error(String(error)), stack];
      }

      _emitHookEnd(hookName, startTime, exitCode, status, errorInfo, startData, event, tool, template);
      _drainAndExit(exitCode);
    });
}

/** Shared HOOK_END logic for runHook and runHookAsync */
function _emitHookEnd(
  hookName: string,
  startTime: number,
  exitCode: number,
  status: string,
  errorInfo: [Error, string] | null,
  startData: Record<string, unknown>,
  event: string,
  tool: null | string,
  template: string,
): void {
  // Retroactive HOOK_START to per-context log (context_path resolved after main runs)
  const resolvedAfter = _getContextPath();
  if (resolvedAfter && fs.existsSync(resolvedAfter)) {
    hookLog("info", hookName, "HOOK_START", { data: startData });
  }

  const durationMs = Math.round((performance.now() - startTime) * 10) / 10;
  const endEvent = _lastHookEvent ?? event;
  const endTool = _lastToolName ?? tool;
  const endData: Record<string, unknown> = {
    lifecycle: "end",
    status,
    durationMs,
    exitCode,
    template,
    event: endEvent,
  };
  if (endTool) endData.tool = endTool;

  if (errorInfo) {
    const [err, tb] = errorInfo;
    endData.errorType = err.constructor.name;
    hookLog("error", hookName, `[${endEvent}] ${err.constructor.name}: ${String(err).replaceAll(/[\n\r]/g, " ").slice(0, 200)}`, { tracebackStr: tb });
    hookLog("error", hookName, `HOOK_END: ${err}`, { data: endData, tracebackStr: tb });
  } else if (status === "blocked") {
    hookLog("warn", hookName, "HOOK_END", { data: endData });
  } else {
    hookLog("info", hookName, "HOOK_END", { data: endData });
  }
}

/**
 * Drain stdout before exiting to ensure pipe consumers receive all data.
 * On Windows, stdout to a pipe is fully buffered — process.exit() can
 * discard unflushed data. This waits for the write buffer to drain.
 */
function _drainAndExit(code: number): void {
  // If stdout is already finished or not writable, exit immediately
  if (!process.stdout.writable || process.stdout.writableFinished) {
    process.exitCode = code;
    return;
  }

  // Attempt to end stdout and wait for drain
  const timeout = setTimeout(() => {
    process.exitCode = code;
  }, 1000); // safety fallback
  process.stdout.end(() => {
    clearTimeout(timeout);
    process.exitCode = code;
  });
}

export {hookLog, logBlocking, logDebug, logDiagnostic, logError, logHookError, logInfo, logWarn, setContextPath, setSessionId} from "../runtime/logger.js";

import {execSync} from 'node:child_process'
import {copyFileSync, existsSync, readFileSync, renameSync, statSync, writeFileSync} from 'node:fs'
import * as os from 'node:os'
import path from 'node:path'

// TODO: Remove when upstream LSP spawn bug is fixed.
// Tracks: https://github.com/anthropics/claude-code/issues/17136
//         https://github.com/anthropics/claude-code/issues/19658

/** The spawn options pattern in Claude Code's bundled cli.js (v2.1.63). */
const SPAWN_FIND =
  '{stdio:["pipe","pipe","pipe"],env:X?.env?{...globalThis.process.env,...X.env}:void 0,cwd:X?.cwd,windowsHide:!0}'

/** Replacement: same options + shell:true on Windows. */
const SPAWN_REPLACE =
  '{stdio:["pipe","pipe","pipe"],env:X?.env?{...globalThis.process.env,...X.env}:void 0,cwd:X?.cwd,windowsHide:!0,shell:process.platform==="win32"}'

/**
 * Patches the npm-installed Claude Code cli.js to add `shell: true` on Windows
 * for LSP subprocess spawning, then renames the native binary so the npm shim
 * takes precedence on PATH.
 *
 * Safe ordering: locate → backup → patch → verify → rename.
 * Never throws. On unknown failure, emits a warning and returns.
 */
export async function ensureLspPatch(options: {
  debugLog: (msg: string) => void
  warn: (msg: string) => void
}): Promise<void> {
  const {debugLog, warn} = options

  try {
    // Step 1 — Guard: only applies on Windows
    if (process.platform !== 'win32') return

    // Step 2 — Locate npm cli.js
    let npmPrefix: string
    try {
      npmPrefix = execSync('npm config get prefix', {timeout: 3000, encoding: 'utf8'}).trim()
    } catch {
      debugLog('LSP patch: could not determine npm prefix, skipping')
      return
    }

    const cliJsPath = path.join(
      npmPrefix, 'node_modules', '@anthropic-ai', 'claude-code', 'cli.js',
    )
    if (!existsSync(cliJsPath)) {
      warn('Windows LSP fix requires: npm i -g @anthropic-ai/claude-code')
      return
    }

    // Step 3 — Locate npm shim
    const shimPath = path.join(npmPrefix, 'claude.cmd')
    if (!existsSync(shimPath)) {
      warn('npm claude.cmd shim not found, skipping LSP patch')
      return
    }

    // Step 4 — Read cli.js and check patch status
    let content: string
    try {
      content = readFileSync(cliJsPath, 'utf8')
    } catch {
      warn('LSP patch: cannot read cli.js, skipping')
      return
    }

    if (content.includes('shell:process.platform==="win32"')) {
      debugLog('LSP patch: already applied')
      renamNativeBinary(debugLog, warn)
      return
    }

    // Step 5 — Patch cli.js
    const parts = content.split(SPAWN_FIND)
    if (parts.length !== 2) {
      warn('LSP patch: spawn pattern changed upstream — patch skipped, LSP may not work')
      return
    }

    const patched = parts.join(SPAWN_REPLACE)

    // Backup original (only if .bak doesn't already exist)
    const bakPath = cliJsPath + '.bak'
    if (!existsSync(bakPath)) {
      try {
        copyFileSync(cliJsPath, bakPath)
        debugLog(`LSP patch: backed up cli.js to ${bakPath}`)
      } catch {
        // Non-fatal — continue with patch
        debugLog('LSP patch: could not create backup, continuing')
      }
    }

    // Atomic write: write to tmp, then rename over original
    const tmpPath = cliJsPath + '.tmp'
    try {
      writeFileSync(tmpPath, patched, 'utf8')
      renameSync(tmpPath, cliJsPath)
      debugLog('LSP patch: applied successfully')
    } catch (error: unknown) {
      const {code} = (error as NodeJS.ErrnoException)
      if (code === 'EACCES' || code === 'EPERM') {
        warn('LSP patch: permission denied writing cli.js')
      } else {
        warn(`LSP patch: write failed — ${code ?? error}`)
      }

      return
    }

    // Step 6 — Rename native binary
    renamNativeBinary(debugLog, warn)
  } catch (error) {
    // Catch-all: never let this function throw
    warn(`LSP patch: unexpected error — ${error}`)
  }
}

/**
 * Renames the native Claude binary in ~/.local/bin/ so the npm shim
 * (which points to the patched cli.js) takes precedence on PATH.
 */
function renamNativeBinary(
  debugLog: (msg: string) => void,
  warn: (msg: string) => void,
): void {
  const localBin = path.join(os.homedir(), '.local', 'bin')

  for (const name of ['claude.exe', 'claude']) {
    const src = path.join(localBin, name)
    if (!existsSync(src)) continue

    try {
      const stat = statSync(src)
      // Native Bun binary is ~242MB; npm shim is tiny
      if (stat.size <= 1_000_000) continue

      const ext = path.extname(name)
      const base = path.basename(name, ext)
      const target = path.join(localBin, `${base}-native${ext}`)

      if (existsSync(target)) {
        debugLog(`LSP patch: ${target} already exists, skipping rename`)
        continue
      }

      renameSync(src, target)
      debugLog(`LSP patch: renamed ${src} → ${target}`)
    } catch (error: unknown) {
      const {code} = (error as NodeJS.ErrnoException)
      if (code === 'EACCES' || code === 'EPERM') {
        warn(`Cannot rename ${src} — rename manually to ${src.replace(name, name.replace('claude', 'claude-native'))}`)
      } else {
        debugLog(`LSP patch: rename failed for ${src} — ${code ?? error}`)
      }
    }
  }
}

/**
 * Main pane driver — orchestrates launching CLI tools in visible panes.
 * Renamed from template's tmux-driver.ts. Single entry point: launchDriverInTmuxOrFallback().
 */

import * as fs from 'node:fs'
import path from 'node:path'

import {
  getTmuxAvailability,
  quoteForSh,
  type TmuxSplitFlag,
} from './launchers/tmux-launcher.js'
import {createPaneLauncher, type PaneBackend, type PaneSplitDirection} from './pane-launcher.js'
import {applyTmuxLaunchEnv, isWindowsPlatform, shouldUseShell} from './runtime/platform-adapter.js'
import {cleanupSentinelIpc, createSentinelIpcPaths} from './runtime/sentinel-ipc.js'
import {execFileAsync, findExecutable} from './runtime/subprocess-utils.js'
import {preflightWindowsTmux, type WindowsTmuxPreflight} from './runtime/tmux-preflight.js'
import {toMsysPosixPath} from './tmux-primitives.js'

/**
 * Resolve a tool path from bash's perspective.
 * Used on Windows where the tmux backend runs commands in bash,
 * but findExecutable() returns Windows paths (.cmd/.exe) that bash can't execute.
 */
async function resolveToolForBash(toolName: string): Promise<null | string> {
  const bash = findExecutable('bash')
  if (!bash) return null
  const result = await execFileAsync(bash, ['-lc', `command -v ${toolName}`], {
    timeout: 3000,
    env: {...process.env, MSYS_NO_PATHCONV: '1'},
  })
  return result.exitCode === 0 ? result.stdout.trim() || null : null
}

export type DriverMode = 'exec' | 'repl'
export type TmuxSplitOption = 'auto' | TmuxSplitFlag

export interface DriverPreflightResult {
  available: boolean
  error?: string
}

export type DriverPreflight =
  (toolPath: string) => DriverPreflightResult | Promise<DriverPreflightResult>

export interface LaunchDriverOptions {
  allowExecFallback?: boolean | undefined
  args?: string[] | undefined
  autoClose?: boolean | undefined
  cwd?: string | undefined
  env?: Record<string, string> | undefined
  holdMessage?: string | undefined
  holdPane?: boolean | undefined
  mode?: DriverMode | undefined
  preflight?: DriverPreflight | undefined
  promptPath?: string | undefined
  splitFlag?: TmuxSplitOption | undefined
  splitTarget?: string | undefined
  timeoutMs?: number | undefined
  toolBin?: string | undefined
  toolName: string
}

export interface LaunchDriverResult {
  backend: PaneBackend
  exitCode?: number | undefined
  launched: boolean
  mode: DriverMode
  paneId?: string | undefined
  reason?: string | undefined
  sentinelPath?: string | undefined
  stderr?: string | undefined
  stdout?: string | undefined
  toolPath?: string | undefined
  usedTmux: boolean
}

function buildEnvPrefix(env: Record<string, string>): string {
  return Object.entries(env)
    .map(([key, value]) => `${key}=${quoteForSh(value)}`)
    .join(' ')
}

function quoteForPowerShell(input: string): string {
  return `'${input.replaceAll("'", "''")}'`
}

function buildCommandArgs(
  args: string[],
  mode: DriverMode,
  promptPath?: string,
): string[] {
  if (mode !== 'repl' || !promptPath) return args

  if (isWindowsPlatform()) {
    const absolutePromptPath = path.resolve(promptPath)
    const bootstrap = `Read startup instructions from this file path before taking action: ${absolutePromptPath}. Use that file as the initial context.`
    return [...args, bootstrap]
  }

  const promptText = fs.readFileSync(promptPath, 'utf8')
  return [...args, promptText]
}

function buildShToolCommand(
  toolPath: string,
  args: string[],
  env: Record<string, string>,
  mode: DriverMode,
  promptPath?: string,
): string {
  const envPrefix = buildEnvPrefix(env)
  const commandArgs = buildCommandArgs(args, mode, promptPath)
  const argPart = commandArgs.map((arg) => quoteForSh(arg)).join(' ')
  const base = [envPrefix, quoteForSh(toolPath), argPart]
    .filter(Boolean)
    .join(' ')

  if (mode === 'exec' && promptPath) {
    return `${base} < ${quoteForSh(promptPath)}`
  }

  return base
}

function buildPowerShellToolCommand(
  toolPath: string,
  args: string[],
  env: Record<string, string>,
  mode: DriverMode,
  promptPath?: string,
): string {
  const envPrefix = Object.entries(env)
    .map(([key, value]) => `$env:${key}=${quoteForPowerShell(value)}`)
    .join('; ')

  const commandArgs = buildCommandArgs(args, mode, promptPath)
  const argArray = commandArgs.map((arg) => quoteForPowerShell(arg)).join(', ')
  const invocation = `& ${quoteForPowerShell(toolPath)}${argArray ? ` @(${argArray})` : ''}`

  const body = mode === 'exec' && promptPath
    ? `Get-Content -Raw -Path ${quoteForPowerShell(promptPath)} | ${invocation}`
    : invocation

  return [envPrefix, body].filter(Boolean).join('; ')
}

function wrapPaneCommand(
  backend: PaneBackend,
  command: string,
  sentinelPath: string,
  autoClose: boolean,
  holdPane: boolean,
  holdMessage: string,
): string {
  if (backend === 'tmux') {
    // On Windows, convert sentinel path to POSIX for bash redirections.
    // MSYS2 bash maps /c/Users/.../file to C:\Users\...\file on disk,
    // so Node.js reads the same physical file via its original Windows path.
    const safePath = isWindowsPlatform()
      ? toMsysPosixPath(sentinelPath) : sentinelPath
    const base = `${command}; code=$?; printf '%s' "$code" > ${quoteForSh(safePath)}`

    if (autoClose) {
      return `${base}; tmux kill-pane -t "$TMUX_PANE" >/dev/null 2>&1 || true; exit $code`
    }

    if (holdPane) {
      return `${base}; echo; echo ${quoteForSh(holdMessage)}; exec bash`
    }

    return `${base}; exit $code`
  }

  const base = `${command}; $code = $LASTEXITCODE; Set-Content -Path ${quoteForPowerShell(sentinelPath)} -Value $code -NoNewline`

  if (holdPane && !autoClose) {
    return `${base}; Write-Host ''; Write-Host ${quoteForPowerShell(holdMessage)}; Read-Host -Prompt 'Press Enter to close' | Out-Null`
  }

  return `${base}; exit $code`
}

function mapSplitDirection(splitFlag: TmuxSplitOption | undefined): PaneSplitDirection {
  if (splitFlag === 'auto') return 'auto'
  if (splitFlag === '-v') return 'v'
  return 'h'
}

export function isTruthy(value: string | undefined): boolean {
  if (!value) return false
  const normalized = value.trim().toLowerCase()
  return normalized === '1' || normalized === 'true' || normalized === 'yes' || normalized === 'on'
}

export function resolveToolPath(toolName: string, toolBin?: string): null | string {
  const bin = toolBin?.trim() || toolName
  return findExecutable(bin)
}

export function buildTmuxLaunchEnv(
  envVars: Record<string, string>,
  platform: NodeJS.Platform = process.platform,
): Record<string, string> {
  return applyTmuxLaunchEnv(envVars, platform)
}

export function getWindowsTmuxPreflightFailureReason(
  backend: PaneBackend,
  platform: NodeJS.Platform = process.platform,
  preflight: () => WindowsTmuxPreflight = preflightWindowsTmux,
): null | string {
  if (backend !== 'tmux' || !isWindowsPlatform(platform)) return null
  const result = preflight()
  if (result.available) return null
  return result.reason ?? 'Windows tmux preflight failed'
}

export function withWindowsTmuxWinpty(
  command: string,
  backend: PaneBackend,
  platform: NodeJS.Platform = process.platform,
): string {
  if (backend !== 'tmux' || !isWindowsPlatform(platform)) return command
  return `winpty bash -lc ${quoteForSh(command)}`
}

function buildCommandForBackend(
  backend: PaneBackend,
  toolPath: string,
  args: string[],
  envVars: Record<string, string>,
  mode: DriverMode,
  promptPath?: string,
): string {
  if (backend === 'tmux') {
    return buildShToolCommand(toolPath, args, envVars, mode, promptPath)
  }

  return buildPowerShellToolCommand(toolPath, args, envVars, mode, promptPath)
}

export async function launchDriverInTmuxOrFallback(
  options: LaunchDriverOptions,
