/**
 * Centralized CLI argument construction for agent subprocesses.
 * Single source of truth for Claude CLI and Codex CLI flag patterns,
 * platform quoting, model tier resolution, and env setup.
 */

import { CLAUDE_MODELS, CODEX_MODELS } from "./models.js";
import type { PreflightCommandConfig } from "./preflight.js";
import { getInternalSubprocessEnv, shellQuoteWin } from "./subprocess-utils.js";



// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export type InvocationMode = "preflight" | "print" | "structured";
export type CliProvider = "claude" | "codex";
export type ModelTier = "fast" | "smart" | "standard";

const VALID_SANDBOXES = ["read-only", "workspace-write", "danger-full-access"] as const;
export type CodexSandbox = (typeof VALID_SANDBOXES)[number];

export function isCodexSandbox(value: string): value is CodexSandbox {
  return (VALID_SANDBOXES as readonly string[]).includes(value);
}

export interface CliArgSpec {
  extraArgs?: string[];
  jsonSchema?: Record<string, unknown>;
  maxTurns?: number;
  mode: InvocationMode;
  model: ModelTier | string;
  outputFilePath?: string;
  outputSchemaPath?: string;
  provider: CliProvider;
  sandbox?: CodexSandbox;
  systemPrompt?: string;
}

/** Codex REPL spec — model optional (Codex uses its default when omitted). */
export interface CodexReplSpec {
  extraArgs?: string[];
  mode: "repl";
  model?: ModelTier | string;
  provider: "codex";
  sandbox?: CodexSandbox;
  yolo?: boolean;
}

export interface CliInvocation {
  args: string[];
  cliName: string;
  env: Record<string, string | undefined>;
  needsShell: boolean;
}

// ---------------------------------------------------------------------------
// Model Tier Resolution
// ---------------------------------------------------------------------------

export const MODEL_TIERS: Record<ModelTier, string> = {
  fast: CLAUDE_MODELS.haiku,
  standard: CLAUDE_MODELS.sonnet,
  smart: CLAUDE_MODELS.opus,
};

export const CODEX_MODEL_TIERS: Record<ModelTier, string> = {
  fast: CODEX_MODELS.spark,
  standard: CODEX_MODELS.codex,
  smart: CODEX_MODELS.codex,
};

export const TIER_TIMEOUTS: Record<ModelTier, number> = {
  fast: 15,
  standard: 30,
  smart: 90,
};

export function isModelTier(value: string): value is ModelTier {
  return value in MODEL_TIERS;
}

export function resolveModel(model: ModelTier | string): string {
  if (isModelTier(model)) return MODEL_TIERS[model];
  return model;
}

export function resolveModelForProvider(
  model: ModelTier | string,
  provider: CliProvider,
): string {
  if (!isModelTier(model)) return model;
  return provider === "codex" ? CODEX_MODEL_TIERS[model] : MODEL_TIERS[model];
}

export function getTierTimeout(tier: ModelTier): number {
  return TIER_TIMEOUTS[tier];
}

/** Resolve a Codex model: tier resolution + pass-through. No aliases (those are skill-specific). */
export function resolveCodexModel(input: string): string {
  if (isModelTier(input)) return CODEX_MODEL_TIERS[input as ModelTier];
  return input;
}

// ---------------------------------------------------------------------------
// Core Builder
// ---------------------------------------------------------------------------

export function buildCliInvocation(spec: CliArgSpec | CodexReplSpec): CliInvocation {
  const env = getInternalSubprocessEnv();
  delete env.ANTHROPIC_API_KEY;

  if (spec.mode === "repl") {
    const resolvedModel = spec.model ? resolveModelForProvider(spec.model, spec.provider) : undefined;
    return buildCodexReplInvocation(spec, resolvedModel, env);
  }

  const resolvedModel = resolveModelForProvider((spec as CliArgSpec).model, spec.provider);
  const isWin = process.platform === "win32";
  const empty = isWin ? '""' : "";

  if (spec.provider === "claude") {
    return buildClaudeInvocation(spec as CliArgSpec, resolvedModel, isWin, empty, env);
  }

  return buildCodexInvocation(spec as CliArgSpec, resolvedModel, env);
}

function buildClaudeInvocation(
  spec: CliArgSpec,
  model: string,
  isWin: boolean,
  empty: string,
  env: Record<string, string | undefined>,
): CliInvocation {
  const args: string[] = [];

  args.push("--model", model);

  if (spec.mode === "print") {
    args.push("--print");
  } else {
    // structured and preflight both use json output
    args.push("--output-format", "json");

    if (spec.jsonSchema) {
      args.push("--json-schema", shellQuoteWin(JSON.stringify(spec.jsonSchema)));
    }

    const maxTurns = spec.mode === "preflight" ? 1 : (spec.maxTurns ?? 3);
    args.push("--max-turns", String(maxTurns));
  }

  args.push("--setting-sources", empty, "-p", "--no-session-persistence");

  if (spec.systemPrompt) {
    args.push("--system-prompt", shellQuoteWin(spec.systemPrompt));
  }

  if (spec.extraArgs) {
    args.push(...spec.extraArgs);
  }

  return { cliName: "claude", args, needsShell: isWin, env };
}

function buildCodexInvocation(
  spec: CliArgSpec,
  model: string,
  env: Record<string, string | undefined>,
): CliInvocation {
  const args: string[] = ["exec"];

  if (spec.sandbox) {
    args.push("--sandbox", spec.sandbox);
  }

  args.push("--model", model);

  if (spec.outputSchemaPath) {
    args.push("--output-schema", spec.outputSchemaPath);
  }

  if (spec.outputFilePath) {
    args.push("-o", spec.outputFilePath);
  }

  args.push("-");

  if (spec.extraArgs) {
    args.push(...spec.extraArgs);
  }

  return { cliName: "codex", args, needsShell: false, env };
}

function buildCodexReplInvocation(
  spec: CodexReplSpec,
  model: string | undefined,
  env: Record<string, string | undefined>,
): CliInvocation {
  const args: string[] = [];
  if (spec.yolo) args.push("--dangerously-bypass-approvals-and-sandbox");
  if (spec.sandbox) args.push("--sandbox", spec.sandbox);
  if (model) args.push("--model", model);
  if (spec.extraArgs) args.push(...spec.extraArgs);
  return { cliName: "codex", args, needsShell: false, env };
}

// ---------------------------------------------------------------------------
// Convenience Presets
// ---------------------------------------------------------------------------

export function preflightSpec(provider: CliProvider, model: string): CliArgSpec {
  if (provider === "codex") {
    return {
      provider: "codex",
      model,
      mode: "preflight",
      sandbox: "read-only",
    };
  }

  return {
    provider: "claude",
    model,
    mode: "preflight",
  };
}

export function inferenceSpec(model: ModelTier | string): CliArgSpec {
  return {
    provider: "claude",
    model,
    mode: "print",
  };
}

export function reviewSpec(
  provider: CliProvider,
  model: string,
  schema: Record<string, unknown>,
  systemPrompt?: string,
): CliArgSpec {
  if (provider === "codex") {
    return {
      provider: "codex",
      model,
      mode: "structured",
      sandbox: "read-only",
    };
  }

  return {
    provider: "claude",
    model,
    mode: "structured",
    jsonSchema: schema,
    ...(systemPrompt ? {systemPrompt} : {}),
  };
}

export function codexReplSpec(
  model?: string,
  sandbox?: CodexSandbox,
  yolo?: boolean,
): CodexReplSpec {
  return {
    provider: "codex",
    mode: "repl",
    ...(model ? {model} : {}),
    ...(sandbox ? {sandbox} : {}),
    ...(yolo === undefined ? {} : {yolo}),
  };
}

export function preflightCommandConfig(provider: CliProvider): PreflightCommandConfig {
  const input = "Respond with exactly: ok";

  return {
    cliName: provider === "claude" ? "claude" : "codex",
    buildArgs: (model: string) => buildCliInvocation(preflightSpec(provider, model)).args,
    input,
  };
}

export {CLAUDE_MODELS, CODEX_MODELS} from "./models.js";

/**
 * Inference utility for AI-powered text processing.
 * Unified interface for Claude API calls using the claude CLI.
 * See SPEC.md §6
 */

import { execFileSync } from "node:child_process";

import { logDebug, logWarn } from "./logger.js";
import { STOP_WORDS } from "./stop-words.js";
import type { InferenceResult } from "../types.js";
import {
  buildCliInvocation,
  getTierTimeout,
  inferenceSpec,
  isModelTier,
  resolveModel,
  TIER_TIMEOUTS,
} from "./cli-args.js";
import { CODEX_MODELS } from "./models.js";
import { execFileAsync } from "./subprocess-utils.js";

const CONTEXT_ID_PRIMARY_MODEL = CODEX_MODELS.spark;

/**
 * Run inference using the claude CLI.
 * See SPEC.md §6.1
 */
export function inference(
  systemPrompt: string,
  userPrompt: string,
  level = "fast",
  timeout?: number,
  options?: { model?: string },
): InferenceResult {
  const startTime = Date.now();
  const modelInput = options?.model ?? level;
  const timeoutSec = timeout ?? (isModelTier(modelInput) ? getTierTimeout(modelInput) : TIER_TIMEOUTS.fast);
  const fullPrompt = `${systemPrompt}\n\n${userPrompt}`;

  const invocation = buildCliInvocation(inferenceSpec(modelInput));
  const isWin = invocation.needsShell;

  // Prompt arg needs Windows quoting when using shell mode
  let promptArg = fullPrompt;
  if (isWin) {
    promptArg = '"' + fullPrompt.replaceAll(/\r?\n/g, " ").replaceAll('"', '""') + '"';
  }

  try {
    const stdout = execFileSync(
      invocation.cliName,
      [...invocation.args, promptArg],
      {
        timeout: timeoutSec * 1000,
        env: invocation.env,
        encoding: "utf8",
        stdio: ["pipe", "pipe", "pipe"],
        shell: isWin,
      },
    );

    const latencyMs = Date.now() - startTime;
    return {
      success: true,
      output: stdout.trim(),
      latencyMs,
    };
  } catch (error: unknown) {
    const latencyMs = Date.now() - startTime;

    if (error.code === "ETIMEDOUT" || error.killed) {
      return {
        success: false,
        output: "",
        error: `Timeout after ${timeoutSec}s`,
        latencyMs,
      };
    }

    if (error.code === "ENOENT") {
      return {
        success: false,
        output: "",
        error: "claude CLI not found",
        latencyMs,
      };
    }

    // Non-zero exit code
    if (error.status !== undefined && error.status !== 0) {
      return {
        success: false,
        output: (error.stdout ?? "").toString().trim(),
        error: (error.stderr ?? "").toString().trim() || `Exit code: ${error.status}`,
        latencyMs,
      };
    }

    return {
      success: false,
      output: "",
      error: String(error),
      latencyMs,
    };
  }
}

// §6.2 — System prompt for keyword extraction
const CONTEXT_ID_SYSTEM_PROMPT = `Extract 6-12 keywords from what the user wants to do.

Rules:
- Output 6-12 keywords only
- Keywords: nouns, verbs, adjectives, technical terms, proper names
- NO function words: the, to, with, for, in, a, an, of, on, is, it, and, or, that, this, be, as, at, by, from
- Most important/specific words preferred
- No punctuation, no quotes

Output ONLY the keywords separated by spaces, nothing else.`;

/**
 * Generate a keyword summary of a user prompt.
 * Uses Sonnet (standard tier). Returns null if inference fails.
 * See SPEC.md §6.2
 */
export function generateSemanticSummary(
  prompt: string,
  timeout = 15,
): null | string {
  const result = inference(CONTEXT_ID_SYSTEM_PROMPT, prompt, "standard", timeout);

  if (!result.success || !result.output) return null;

  let summary = result.output.trim();
  summary = summary.replaceAll(/^["']+|["']+$/g, "");
  summary = summary.replace(/[.!?]+$/, "");

  // Filter stop words
  summary = filterStopWords(summary);

  const words = summary.split(/\s+/);
  if (words.length < 6 || words.length > 12) return null;

  return summary;
}

// §6.3 — System prompt for context ID slug generation
const CONTEXT_ID_SLUG_PROMPT = `You generate short title phrases for work sessions. These become folder names like \`260206-1959-fix-auth-middleware-redirect-loop-session-timeout\`.

Users scan 100+ such names to find past sessions. Your title must make THIS session instantly recognizable.

Rules:
- Exactly 8-12 lowercase words
- First word is an action verb (fix, add, implement, refactor, update, create, remove, optimize, debug, migrate, integrate, configure, deploy, scaffold, restructure)
- Coherent phrase, not disjointed keywords — reads like a short task description
- Prefer specific technical terms over generic words
- No articles (the, a, an), no pronouns, no filler words, no punctuation, no quotes
- Input may come from speech-to-text with filler words (uh, um, like, you know, basically, so) — ignore them entirely

Examples:

Input: "um so basically I need to like fix the auth bug in the login page"
{"slug": "fix authentication bug login page redirect session handling flow"}

Input: "hey uh can we add dark mode to the settings page"
{"slug": "add dark mode toggle settings page user preference storage"}

Input: "the context ids are bad can we change how we generate them towards a summary"
{"slug": "improve context id generation use prompt summary slugs"}

Input: "I want to refactor the database connection pooling for PostgreSQL"
{"slug": "refactor postgresql database connection pooling optimize query performance"}

Input: "so like you know the webhook retry logic is broken and stuff"
{"slug": "fix webhook retry logic broken error handling recovery mechanism"}

Input: "update the CI pipeline to cache node modules between runs"
{"slug": "update ci pipeline cache node modules between workflow runs"}

Respond with ONLY a JSON object: {"slug": "your 8-12 word phrase here"}`;

/**
 * Generate a 5-12 word context ID slug from a user prompt.
 * Uses 5.3 Codex Spark first, then falls back to current fast tier for resilience.
 * See SPEC.md §6.3
 */
export function generateContextIdSlug(
  prompt: string,
  timeout = 3,
): null | string {
  const truncated = prompt.slice(0, 500);

  const sparkResult = inference(
    CONTEXT_ID_SLUG_PROMPT,
    truncated,
    "fast",
    timeout,
    { model: CONTEXT_ID_PRIMARY_MODEL },
  );
  if (!sparkResult.success || !sparkResult.output) {
    logWarn(
      "inference",
      `Context ID slug Spark (${CONTEXT_ID_PRIMARY_MODEL}) failed or returned empty output. Falling back to ${resolveModel("fast")}`,
    );
  }

  const result = sparkResult.success && sparkResult.output ? sparkResult : inference(CONTEXT_ID_SLUG_PROMPT, truncated, "fast", timeout);

  if (!result.success || !result.output) {
    logWarn("inference", `Context ID slug inference failed: ${result.error}`);
    return null;
  }

  const raw = result.output.trim();

  // Parse JSON response, fall back to raw text
  let slug: null | string = null;
  try {
    const parsed = JSON.parse(raw);
    if (parsed && typeof parsed === "object" && "slug" in parsed) {
      slug = parsed.slug;
    }
  } catch {
    // Fall through to raw text
  }

  if (!slug) slug = raw;

  // Clean up
  slug = slug.replaceAll(/^["'`]+|["'`]+$/g, "");
  slug = slug.replace(/[.!?]+$/, "");
  slug = slug.replaceAll('-', " ");
  slug = slug.replaceAll(/[^a-zA-Z0-9 ]/g, "");
  slug = slug.replaceAll(/\s+/g, " ").trim();

  const words = slug.split(" ");

  if (words.length > 12) words.length = 12;
  if (words.length < 5) {
    logDebug("inference", `Context ID slug too short (${words.length} words): '${slug}'`);
    return null;
  }

  const resultSlug = words.join(" ");
  logDebug("inference", `Generated context ID slug: '${resultSlug}' (${result.latencyMs}ms)`);
  return resultSlug;
}

/**
 * Async version of inference() that does NOT block the event loop.
 * Use for parallel AI calls (e.g., Stage 3 parallel summarizers).
 * Uses execFileAsync and getInternalSubprocessEnv for proper subprocess isolation.
 */
export async function inferenceAsync(
  systemPrompt: string,
  userPrompt: string,
  level = "fast",
  timeout?: number,
  options?: { model?: string },
): Promise<InferenceResult> {
  const startTime = Date.now();
  const modelInput = options?.model ?? level;
  const timeoutSec = timeout ?? (isModelTier(modelInput) ? getTierTimeout(modelInput) : TIER_TIMEOUTS.fast);
  const timeoutMs = timeoutSec * 1000;
  const fullPrompt = `${systemPrompt}\n\n${userPrompt}`;

  const invocation = buildCliInvocation(inferenceSpec(modelInput));
  const isWin = invocation.needsShell;

  // Prompt arg needs Windows quoting when using shell mode
  const promptArg = isWin
    ? ('"' + fullPrompt.replaceAll(/\r?\n/g, " ").replaceAll('"', '""') + '"')
    : fullPrompt;

  const result = await execFileAsync(
    invocation.cliName,
    [...invocation.args, promptArg],
    { timeout: timeoutMs, env: invocation.env, shell: isWin },
  );

  const latencyMs = Date.now() - startTime;

  if (result.killed) {
    return { success: false, output: "", error: `Timeout after ${timeoutSec}s`, latencyMs };
  }

  if (result.exitCode !== 0) {
    return {
      success: false,
      output: result.stdout.trim(),
      error: result.stderr.trim() || `Exit code: ${result.exitCode}`,
      latencyMs,
    };
  }

  return { success: true, output: result.stdout.trim(), latencyMs };
}

/**
 * Filter stop words from text.
 * See SPEC.md §6.4
 */
function filterStopWords(text: string): string {
  return text
    .toLowerCase()
    .split(/\s+/)
    .filter((w) => !STOP_WORDS.has(w) && w.length > 1)
    .join(" ");
}

/**
 * Unified logging for all hooks and libraries.
 *
 * Log format: JSONL (one JSON object per line)
 * Log location: _output/hook-log.jsonl (global, all sessions)
 * Filter by session using the "sid" field.
 *
 * stderr is OPT-IN: convenience functions (logDebug, logInfo, logWarn, logError)
 * write to file only by default. To also write to stderr (visible to Claude Code
 * as "hook error"), pass { stderr: true } or use logBlocking().
 * logHookError() always writes to stderr (unhandled errors must be visible).
 *
 * Environment variables:
 * - HOOK_LOG_DISABLE=1: Disable all file logging
 * - HOOK_LOG_LEVEL=warn: Minimum level to log (default: debug)
 * - HOOK_ERROR_LOG_DISABLE=1: Legacy alias for HOOK_LOG_DISABLE
 *
 * Never throws. No buffering. Stdlib only.
 * See SPEC.md §3
 */

import * as fs from "node:fs";
import path from "node:path";

const LEVELS: Record<string, number> = {
  debug: 0,
  info: 1,
  warn: 2,
  error: 3,
};

const MAX_LOG_LINES = 10_000; // Max lines in global log before pruning

// Module-level session ID cache
let _cachedSessionId: null | string = null;

// Module-level context path cache (kept for external callers)
let _cachedContextPath: null | string = null;
let _contextResolved = false;

/**
 * Set the session ID for this process. All subsequent log calls include it.
 */
export function setSessionId(sessionId: null | string): void {
  _cachedSessionId = sessionId;
}

/**
 * Set the context path for this process. Kept for external callers.
 */
export function setContextPath(contextPath: null | string): void {
  _cachedContextPath = contextPath;
  _contextResolved = true;
}

export function getContextPath(): null | string {
  if (!_contextResolved) {
    _contextResolved = true; // Don't retry
  }

  return _cachedContextPath;
}

function getMinLevel(): number {
  const env = (process.env.HOOK_LOG_LEVEL ?? "debug").toLowerCase();
  return LEVELS[env] ?? 0;
}

function isDisabled(): boolean {
  return (
    process.env.HOOK_LOG_DISABLE === "1" ||
    process.env.HOOK_ERROR_LOG_DISABLE === "1" ||
    process.env.CCNATIVE_DEBUG_DISABLE === "1"
  );
}

function getProjectRoot(): string {
  return process.env.CLAUDE_PROJECT_DIR || process.cwd();
}

/**
 * Write a structured log entry to the global hook log.
 *
 * All entries go to _output/hook-log.jsonl. Use the "sid" field
 * (set via setSessionId) to filter by session.
 */
export function hookLog(
  level: string,
  hookName: string,
  message: string,
  opts?: {
    component?: string;
    data?: unknown;
    stderr?: boolean;
    tracebackStr?: string;
  },
): void {
  try {
    const levelLower = level.toLowerCase();
    const levelNum = LEVELS[levelLower] ?? 0;
    const component = opts?.component ?? "";
    const tracebackStr = opts?.tracebackStr ?? "";
    const stderrEnabled = opts?.stderr === true;

    // Write to stderr
    if (stderrEnabled) {
      const prefix = component
        ? `[${hookName}:${component}]`
        : `[${hookName}]`;
      process.stderr.write(`${prefix} ${message}\n`);
      if (tracebackStr) {
        process.stderr.write(tracebackStr + "\n");
      }
    }

    // Check if file logging is enabled
    if (isDisabled()) return;

    // Check minimum level
    if (levelNum < getMinLevel()) return;

    // Build JSONL entry
    const now = new Date();
    const ts = now.toISOString().replace("Z", "").slice(0, 23);
    const entry: Record<string, unknown> = {
      ts,
      level: levelLower,
      hook: hookName,
      msg: message,
    };
    if (_cachedSessionId) entry.sid = _cachedSessionId;
    if (component) entry.component = component;
    if (opts?.data !== undefined && opts.data !== null) {
      try {
        JSON.stringify(opts.data);
        entry.data = opts.data;
      } catch {
        entry.data = String(opts.data);
      }
    }

    if (tracebackStr) entry.tb = tracebackStr.trimEnd();

    const line = JSON.stringify(entry) + "\n";

    // Always write to global log
    const logPath = path.join(getProjectRoot(), "_output", "hook-log.jsonl");

    // Ensure directory exists
    const dir = path.dirname(logPath);
    fs.mkdirSync(dir, { recursive: true });

    // Line-count guard: prune to last MAX_LOG_LINES
    try {
      if (fs.existsSync(logPath)) {
        const content = fs.readFileSync(logPath, "utf8");
        const lines = content.split(/\r?\n/);
        if (lines.length > MAX_LOG_LINES) {
          fs.writeFileSync(
            logPath,
            lines.slice(lines.length - MAX_LOG_LINES).join("\n"),
            "utf8",
          );
        }
      }
    } catch {
      // ignore
    }

    fs.appendFileSync(logPath, line, "utf8");
  } catch {
    // Never crash
  }
}

export function logDebug(hookName: string, message: string, opts?: Record<string, unknown>): void {
  hookLog("debug", hookName, message, opts);
}

export function logInfo(hookName: string, message: string, opts?: Record<string, unknown>): void {
  hookLog("info", hookName, message, opts);
}

export function logWarn(hookName: string, message: string, opts?: Record<string, unknown>): void {
  hookLog("warn", hookName, message, opts);
}

export function logError(hookName: string, message: string, opts?: Record<string, unknown>): void {
  hookLog("error", hookName, message, opts);
}

/**
 * Log an error that SHOULD be visible to user/model via stderr.
 * Use for real problems needing attention, not routine diagnostics.
 */
export function logBlocking(hookName: string, message: string, opts?: Record<string, unknown>): void {
  hookLog("error", hookName, message, { ...opts, stderr: true });
}

/**
 * Log a structured diagnostic entry at a hook decision point.
 * See SPEC.md §3.8
 */
export function logDiagnostic(
  hookName: string,
  phase: string,
  summary: string,
  opts?: {
    component?: string;
    data?: unknown;
    decision?: unknown;
    inputs?: unknown;
    reasoning?: unknown;
  },
): void {
  const diagData: Record<string, unknown> = { phase };
  if (opts?.inputs !== undefined) diagData.inputs = opts.inputs;
  if (opts?.decision !== undefined) diagData.decision = opts.decision;
  if (opts?.reasoning !== undefined) diagData.reasoning = opts.reasoning;
  if (opts?.data && typeof opts.data === "object") {
    Object.assign(diagData, opts.data);
  }

  hookLog("debug", hookName, `[DIAG:${phase}] ${summary}`, {
    component: opts?.component ?? "diag",
    data: diagData,
  });
}

/**
 * Backward-compatible wrapper matching old hook_utils.log_hook_error signature.
 * See SPEC.md §3.6
 */
export function logHookError(
  hookName: string,
  error: Error | string,
  hookEvent = "unknown",
  tracebackStr = "",
): void {
  const errStr = typeof error === "string" ? error : String(error);
  const msg = errStr.replaceAll(/[\n\r]/g, " ").slice(0, 200);
  const errType =
    typeof error === "object" && error !== null
      ? error.constructor.name
      : "Error";
  hookLog("error", hookName, `[${hookEvent}] ${errType}: ${msg}`, {
    tracebackStr,
    stderr: true,
  });
}

/**
 * Shared preflight health check for provider+model availability.
 * Extracted from plan-review/lib/preflight.ts for reuse by unknown hook.
 *
 * Validates that a CLI tool + model combo works by running a minimal "ping" request.
 */

import { logDebug, logWarn } from "./logger.js";
import { execFileAsync, findExecutable, getInternalSubprocessEnv } from "./subprocess-utils.js";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface PreflightCommandConfig {
  buildArgs: (model: string) => string[];
  cliName: string;
  input: string;
}

export interface PreflightCheckResult {
  available: boolean;
  error?: string;
  latencyMs: number;
  model: string;
  provider: string;
}

// ---------------------------------------------------------------------------
// Error Classification
// ---------------------------------------------------------------------------

export function classifyError(
  stderr: string,
  exitCode: null | number,
  killed: boolean,
  signal: null | string,
): string {
  if (killed || signal === "SIGTERM") return "Preflight timed out";
  if (/model.*not found|not available/i.test(stderr)) return "Model not available for this account";
  if (/rate limit|429/i.test(stderr)) return "Rate limited";
  if (/auth|api key|401/i.test(stderr)) return "Authentication failed";
  if (/quota|billing/i.test(stderr)) return "Quota/billing issue";
  return `Exit code ${exitCode}`;
}

// ---------------------------------------------------------------------------
// Single Provider+Model Check
// ---------------------------------------------------------------------------

/**
 * Check if a single provider:model combo is available.
 * Takes a PreflightCommandConfig so callers define their own CLI args.
 */
export async function checkProviderModel(
  provider: string,
  model: string,
  config: PreflightCommandConfig,
  timeoutMs: number,
  hook = "preflight",
): Promise<PreflightCheckResult> {
  const cliPath = findExecutable(config.cliName);
  if (!cliPath) {
    return { provider, model, available: false, latencyMs: 0, error: `CLI '${config.cliName}' not found on PATH` };
  }

  const start = Date.now();
  try {
    const env = getInternalSubprocessEnv();
    const result = await execFileAsync(cliPath, config.buildArgs(model), {
      input: config.input,
      timeout: timeoutMs,
      env: env as Record<string, string>,
      maxBuffer: 1 * 1024 * 1024,
      shell: process.platform === "win32",
    });

    const latencyMs = Date.now() - start;

    if (result.killed || result.signal === "SIGTERM") {
      return { provider, model, available: false, latencyMs, error: "Preflight timed out" };
    }

    if (result.exitCode !== 0) {
      const error = classifyError(result.stderr, result.exitCode, result.killed, result.signal);
      logWarn(hook, `${provider}:${model} failed: ${error} (stderr: ${result.stderr.slice(-200)})`);
      return { provider, model, available: false, latencyMs, error };
    }

    logDebug(hook, `${provider}:${model} passed (${latencyMs}ms)`);
    return { provider, model, available: true, latencyMs };
  } catch (error_) {
    const latencyMs = Date.now() - start;
    const error = error_ instanceof Error ? error_.message : String(error_);
    logWarn(hook, `${provider}:${model} exception: ${error}`);
    return { provider, model, available: false, latencyMs, error };
  }
}

/**
 * Shared I/O for state.json — read, write, serialize.
 * Extracted to avoid circular deps between context-store and task-tracker.
 * See SPEC.md §7.1
 */

import * as fs from "node:fs";
import path from "node:path";

import { atomicWrite } from "./atomic-write.js";
import { getContextDir } from "./constants.js";
import { logWarn } from "./logger.js";
import type { ContextState, Mode } from "../types.js";

/** Mode migration from legacy context_manager values. */
const MODE_MIGRATION: Record<string, Mode> = {
  none: "idle",
  planning: "idle",
  pendingImplementation: "hasStagedWork",
  implementing: "active",
};

/** Legacy state data structure for migration type safety. */
interface LegacyStateData {
  handoffConsumed?: boolean;
  handoffPath?: null | string;
  mode?: string;
  nextArtifactType?: "handoff" | "plan" | null;
  planConsumed?: boolean;
  planHash?: null | string;
  planPath?: null | string;
  workConsumed?: boolean;
}

/**
 * Serialize a ContextState for JSON output.
 * Omits null/undefined keys but keeps false, 0, empty string, and empty arrays.
 */
export function toDict(state: ContextState): Record<string, unknown> {
  const result: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(state)) {
    if (value !== null && value !== undefined) {
      result[key] = value;
    }
  }

  return result;
}

/**
 * Migrate old consumed flags to unified workConsumed.
 * Runs on every state.json read for transparent backward compatibility.
 * Idempotent: safe to run multiple times.
 */
function migrateConsumedFlags(data: Record<string, unknown>): void {
  const legacy = data as LegacyStateData;

  // Skip if already migrated (check both fields and mode)
  const alreadyMigrated =
    typeof legacy.workConsumed === "boolean" &&
    legacy.mode !== "has_plan" &&
    legacy.mode !== "has_handoff";
  if (alreadyMigrated) return;

  const hasPlan = Boolean(legacy.planPath && legacy.planHash);
  const hasHandoff = Boolean(legacy.handoffPath);

  // Migrate consumed flag (plan takes precedence if both exist)
  if (hasPlan && typeof legacy.planConsumed === "boolean") {
    (data as Record<string, unknown>).workConsumed = legacy.planConsumed;
  } else if (hasHandoff && typeof legacy.handoffConsumed === "boolean") {
    (data as Record<string, unknown>).workConsumed = legacy.handoffConsumed;
  } else {
    (data as Record<string, unknown>).workConsumed = false;
  }

  // Migrate mode: has_plan/has_handoff → hasStagedWork
  if (legacy.mode === "has_plan" || legacy.mode === "has_handoff") {
    const artifactType = legacy.mode === "has_handoff" ? "handoff" : "plan";
    (data as Record<string, unknown>).mode = "hasStagedWork";
    (data as Record<string, unknown>).nextArtifactType = artifactType;
  }

  // Set nextArtifactType based on which artifact exists
  if (!legacy.nextArtifactType) {
    if (hasPlan && hasHandoff) {
      // Both exist - conflict resolution: plan priority during migration
      // (Cannot determine "latest" without timestamps - plan takes precedence)
      (data as Record<string, unknown>).nextArtifactType = "plan";
      (data as Record<string, unknown>).handoffPath = null;
    } else if (hasPlan) {
      (data as Record<string, unknown>).nextArtifactType = "plan";
    } else if (hasHandoff) {
      (data as Record<string, unknown>).nextArtifactType = "handoff";
    }
  }

  // Delete old flags (clean cut migration)
  delete (data as Record<string, unknown>).planConsumed;
  delete (data as Record<string, unknown>).handoffConsumed;
}

/**
 * Get path to state.json for a context.
 */
export function statePath(contextId: string, projectRoot?: string): string {
  return path.join(getContextDir(contextId, projectRoot), "state.json");
}

/**
 * Read and parse state.json for a context.
 * Applies legacy mode migration. Returns null if file doesn't exist or is corrupt.
 */
export function readStateJson(
  contextId: string,
  projectRoot?: string,
): ContextState | null {
  const sp = statePath(contextId, projectRoot);
  if (!fs.existsSync(sp)) return null;

  try {
    const raw = fs.readFileSync(sp, "utf8");
    const data = JSON.parse(raw) as Record<string, unknown>;
    migrateConsumedFlags(data); // Migrate before dictToState
    return dictToState(data);
  } catch (error: unknown) {
    logWarn("state_io", `Failed to read state.json for '${contextId}': ${error}`);
    return null;
  }
}

/**
 * Atomically write state.json for a context.
 * Returns [success, error].
 */
export function writeStateJson(
  contextId: string,
  state: ContextState,
  projectRoot?: string,
): [boolean, null | string] {
  const sp = statePath(contextId, projectRoot);
  const dir = path.dirname(sp);
  fs.mkdirSync(dir, { recursive: true });

  const content = JSON.stringify(toDict(state), null, 2);
  return atomicWrite(sp, content);
}

/**
 * Construct a ContextState from a dict, migrating old mode names.
 * Only includes fields that are present in the source data (preserves null-stripping).
 */
export function dictToState(data: Record<string, unknown>): ContextState {
  // Validate required fields
  if (typeof data.id !== "string" || !data.id) {
    throw new Error("dictToState: missing or invalid required field 'id'");
  }

  const rawMode: string =
    typeof data.mode === "string" ? data.mode : "idle";
  const mode: Mode = (MODE_MIGRATION[rawMode] ?? rawMode) as Mode;

  const state: unknown = {
    id: data.id,
    status: data.status ?? "active",
    summary: data.summary ?? "",
    method: data.method ?? "",
    tags: data.tags ?? [],
    createdAt: data.createdAt ?? "",
    lastActive: data.lastActive ?? "",
    mode,
    planAnchors: data.planAnchors ?? [],
    workConsumed: data.workConsumed ?? false,
    sessionIds: data.sessionIds ?? [],
    tasks: data.tasks ?? [],
  };

  // Only set nullable fields if they exist in the source data
  if ("planPath" in data) state.planPath = data.planPath;
  if ("planHash" in data) state.planHash = data.planHash;
  if ("planSignature" in data) state.planSignature = data.planSignature;
  if ("planId" in data) state.planId = data.planId;
  if ("handoffPath" in data) state.handoffPath = data.handoffPath;
  if ("nextArtifactType" in data) state.nextArtifactType = data.nextArtifactType;
  if ("lastSession" in data) state.lastSession = data.lastSession;

  // Migration: planHashConsumed (added in multi-plan context fix)
  state.planHashConsumed = "planHashConsumed" in data
    ? data.planHashConsumed
    : null; // Default for old contexts

  // Preserve method-specific extension data (e.g., cc_native) that isn't
  // part of the core ContextState interface. Without this, round-trip
  // read→write cycles silently drop extension fields.
  for (const key of Object.keys(data)) {
    if (!(key in state)) {
      state[key] = data[key];
    }
  }

  return state as ContextState;
}

/**
 * Core utilities for shared context management.
 * See SPEC.md §14.2, §14.3
 */

import { sanitizeTitle } from "./constants.js";
import { logDebug, logError, logWarn } from "./logger.js";
import { STOP_WORDS } from "./stop-words.js";

/**
 * Print to stderr. For terminal-only UX messages, not diagnostics.
 */
export function eprint(...args: unknown[]): void {
  process.stderr.write(args.map(String).join(" ") + "\n");
}

/**
 * Get current local datetime as Date.
 */
export function nowLocal(): Date {
  return new Date();
}

/**
 * Get current time as ISO 8601 string (local time, no timezone suffix).
 * Matches Python datetime.now().isoformat() behavior.
 */
export function nowIso(): string {
  const d = new Date();
  const year = d.getFullYear();
  const month = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  const hours = String(d.getHours()).padStart(2, "0");
  const minutes = String(d.getMinutes()).padStart(2, "0");
  const seconds = String(d.getSeconds()).padStart(2, "0");
  const ms = String(d.getMilliseconds()).padStart(3, "0");
  return `${year}-${month}-${day}T${hours}:${minutes}:${seconds}.${ms}`;
}

/**
 * Format datetime for display.
 * Returns "YYYY-MM-DD HH:MM:SS"
 * See SPEC.md §14.3
 */
export function formatTimestamp(dt?: Date): string {
  const d = dt ?? nowLocal();
  const year = d.getFullYear();
  const month = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  const hours = String(d.getHours()).padStart(2, "0");
  const minutes = String(d.getMinutes()).padStart(2, "0");
  const seconds = String(d.getSeconds()).padStart(2, "0");
  return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;
}

/**
 * Parse ISO 8601 timestamp string.
 * Returns null if parsing fails.
 * See SPEC.md §14.3
 */
export function parseIsoTimestamp(isoStr: string): Date | null {
  try {
    const normalized = isoStr.replace("Z", "+00:00");
    const d = new Date(normalized);
    if (Number.isNaN(d.getTime())) return null;
    return d;
  } catch {
    return null;
  }
}

/**
 * Normalize a filesystem path for display — always uses forward slashes.
 * No-op on Unix; converts backslashes on Windows.
 */
export function displayPath(p: string): string {
  return p.replaceAll("\\", "/");
}

/**
 * Clean text for stop-word matching in slug generation.
 * Strips apostrophes (i'm -> im), removes punctuation, normalizes whitespace.
 * See SPEC.md §14.2
 */
export function cleanTextForSlug(text: string): string {
  if (!text) return "";
  let result = text.toLowerCase();
  result = result.replaceAll('\'', "");            // i'm -> im, you're -> youre
  result = result.replaceAll(/[^a-z0-9\s]/g, " "); // punctuation -> spaces
  result = result.replaceAll(/\s+/g, " ").trim();
  return result;
}

/**
 * Generate a slug from text using AI inference with stop-word fallbacks.
 * Pipeline: AI inference → stop-word post-filter → stop-word fallback → word-length fallback.
 * Reusable by both context ID generation and plan archival.
 * See SPEC.md §14.2
 */
export function generateSlug(
  text: string,
  maxLen = 150,
  fallbackSlug = "context",
): string {
  if (!text || !text.trim()) return fallbackSlug;

  let slug: null | string = null;
  const cleanedText = cleanTextForSlug(text);

  // Tier 1: AI inference via generateContextIdSlug (sync — uses execFileSync)
  try {
    // eslint-disable-next-line @typescript-eslint/no-require-imports, no-undef
    const { generateContextIdSlug } = require("./inference.js");
    const aiSlug = generateContextIdSlug(text);
    if (aiSlug) {
      const filteredWords = aiSlug
        .split(/\s+/)
        .filter(
          (w: string) => !STOP_WORDS.has(w.toLowerCase()) && w.length > 1,
        );
      if (filteredWords.length >= 5) {
        slug = sanitizeTitle(filteredWords.join(" "), maxLen);
      } else {
        logDebug(
          "utils",
          `AI slug too generic after stop-word filter (${filteredWords.length} words remain), using fallback`,
        );
      }
    }
  } catch (error: unknown) {
    logWarn("utils", `AI slug generation failed, using fallback: ${error}`);
  }

  // Tier 2: Stop-word filtering on cleaned text
  if (!slug) {
    const words = cleanedText
      .split(/\s+/)
      .filter((w) => !STOP_WORDS.has(w) && w.length > 1)
      .slice(0, 12);
    slug = words.length >= 3
      ? sanitizeTitle(words.join(" "), maxLen)
      : sanitizeTitle(
          cleanedText.split(/\s+/).filter((w) => w.length > 2).slice(0, 6).join(" "),
          maxLen,
        ) || fallbackSlug;
  }

  return slug;
}

/**
 * Generate a context ID from a summary string.
 * Format: YYMMDD-HHMM-slug
 * Delegates slug generation to generateSlug().
 * See SPEC.md §14.2
 */
export function generateContextId(
  summary: string,
  existingIds?: Set<string>,
): string {
  const now = new Date();
  const yy = String(now.getFullYear()).slice(2);
  const mm = String(now.getMonth() + 1).padStart(2, "0");
  const dd = String(now.getDate()).padStart(2, "0");
  const hh = String(now.getHours()).padStart(2, "0");
  const min = String(now.getMinutes()).padStart(2, "0");
  const timestamp = `${yy}${mm}${dd}-${hh}${min}`;

  let baseId: string;

  try {
    const slug = generateSlug(summary);
    baseId = `${timestamp}-${slug}`;
  } catch (error: unknown) {
    logError(
      "utils",
      `Context ID generation failed entirely, using timestamp: ${error}`,
    );
    baseId = `${timestamp}-context`;
  }

  if (!existingIds || !existingIds.has(baseId)) {
    return baseId;
  }

  let counter = 2;
  while (existingIds.has(`${baseId}-${counter}`)) {
    counter++;
  }

  return `${baseId}-${counter}`;
}

import {expect} from 'chai'
import sinon from 'sinon'

import {adaptHookCommand, validateCommandsForPlatform} from '../../src/lib/platform-commands.js'

describe('platform-commands', () => {
  describe('adaptHookCommand', () => {
    let platformStub: sinon.SinonStub

    afterEach(() => {
      platformStub?.restore()
    })

    it('is a no-op on non-Windows', () => {
      platformStub = sinon.stub(process, 'platform').value('linux')
      const cmd = 'bun ~/.aiwcli/bin/resolve-run.ts .aiwcli/_core/hooks-ts/session_start.ts'
      expect(adaptHookCommand(cmd)).to.equal(cmd)
    })

    it('expands ~ to absolute home path on Windows', () => {
      platformStub = sinon.stub(process, 'platform').value('win32')
      const cmd = 'bun ~/.aiwcli/bin/resolve-run.ts .aiwcli/_core/hooks-ts/session_start.ts'
      const result = adaptHookCommand(cmd)
      expect(result).to.not.include('~/')
      expect(result).to.include('.aiwcli/bin/resolve-run.ts')
      expect(result).to.include('.aiwcli/_core/hooks-ts/session_start.ts')
      // Should be quoted for paths with spaces
      expect(result).to.match(/bun ".*\.aiwcli\/bin\/resolve-run\.ts"/)
    })

    it('strips bash env-var prefix on Windows', () => {
      platformStub = sinon.stub(process, 'platform').value('win32')
      const cmd = 'NO_COLOR= FORCE_COLOR=2 bun ~/.aiwcli/bin/resolve-run.ts .aiwcli/_core/scripts/status_line.ts'
      const result = adaptHookCommand(cmd)
      expect(result).to.not.include('NO_COLOR=')
      expect(result).to.not.include('FORCE_COLOR=2')
      expect(result).to.match(/^bun "/)
    })

    it('preserves bash env-var prefix on Unix', () => {
      platformStub = sinon.stub(process, 'platform').value('darwin')
      const cmd = 'NO_COLOR= FORCE_COLOR=2 bun ~/.aiwcli/bin/resolve-run.ts .aiwcli/_core/scripts/status_line.ts'
      expect(adaptHookCommand(cmd)).to.equal(cmd)
    })

    it('handles commands without resolver token on Windows', () => {
      platformStub = sinon.stub(process, 'platform').value('win32')
      const cmd = 'echo hello'
      expect(adaptHookCommand(cmd)).to.equal('echo hello')
    })
  })

  describe('validateCommandsForPlatform', () => {
    let platformStub: sinon.SinonStub

    afterEach(() => {
      platformStub?.restore()
    })

    it('is a no-op on Unix', () => {
      platformStub = sinon.stub(process, 'platform').value('linux')
      expect(() => validateCommandsForPlatform(['bun ~/.aiwcli/bin/resolve-run.ts foo'])).to.not.throw()
    })

    it('throws on unexpanded ~/ on Windows', () => {
      platformStub = sinon.stub(process, 'platform').value('win32')
      expect(() => validateCommandsForPlatform(['bun ~/.aiwcli/bin/resolve-run.ts foo'])).to.throw(/unexpanded ~\//)
    })

    it('throws on bash env prefix on Windows', () => {
      platformStub = sinon.stub(process, 'platform').value('win32')
      expect(() => validateCommandsForPlatform(['NO_COLOR= bun something'])).to.throw(/bash env prefix/)
    })

    it('passes for adapted commands on Windows', () => {
      platformStub = sinon.stub(process, 'platform').value('win32')
      const adapted = ['bun "C:/Users/test/.aiwcli/bin/resolve-run.ts" .aiwcli/foo.ts']
      expect(() => validateCommandsForPlatform(adapted)).to.not.throw()
    })
  })
})
